#!/usr/bin/env node
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const OUT = path.join(ROOT, 'output');
const BLOCK = '**** YD001 SOURCE BLOCK ****';
const ENG = '**** ENGLISH ****';
const END = '**** END BLOCK ****';

function patchFile(rel, slug, T) {
  const fp = path.join(OUT, rel);
  const s = fs.readFileSync(fp, 'utf8');
  const applied = new Set();
  const parts = s.split(BLOCK);
  const out = parts.map((block, i) => {
    if (i === 0) return block;
    const slugM = block.match(/^\s*slug: (.+)$/m);
    const seifM = block.match(/^\s*seif: (.+)$/m);
    const markerM = block.match(/^\s*marker: (.+)$/m);
    if (!slugM || slugM[1].trim() !== slug) return BLOCK + block;
    const seif = seifM[1].trim();
    const marker = markerM ? markerM[1].trim() : 'main';
    const key = `${seif}#${marker}`;
    if (!(key in T)) return BLOCK + block;
    const enStart = block.indexOf(ENG);
    const enEnd = block.indexOf(END);
    if (enStart < 0 || enEnd < 0) throw new Error(`ENGLISH/END missing: ${rel} ${key}`);
    const before = block.slice(0, enStart + ENG.length + 1);
    const after = block.slice(enEnd);
    const text = T[key].endsWith('\n') ? T[key] : T[key] + '\n';
    applied.add(key);
    return BLOCK + before + text + after;
  });
  const missing = Object.keys(T).filter((k) => !applied.has(k));
  if (missing.length) throw new Error(`Keys not found in ${rel}: ${missing.join(', ')}`);
  fs.writeFileSync(fp, out.join(''), 'utf8');
  console.log(`OK ${rel} (${applied.size} blocks)`);
}


// --- mechaber (24) ---
patchFile('siman_028/mechaber/part-001.txt', 'mechaber', {
  "1#main": "The laws of covering the blood. In it are 24 seifim. One who slaughters a chayah or bird must cover its blood — whether on his side now or whether they were prepared in his hand. {Rama: And covering is a mitzvah in itself (so appears in Hagahot Ashiri, chapter Kisuy HaDam); but the shechitah is kosher even if he acted willfully and did not cover (Beit Yosef, and so Chayei Adam, and so Kol Bo).}",
  "2#main": "He must bless before covering: Who has sanctified us with His commandments and commanded us regarding covering blood with earth. {Rama: One who slaughters for the first time recites shehecheyanu on the covering but not on the shechitah, because it harms a creature (ancient practices in the name of R' Yedidya of Shapiro).}",
  "3#main": "Koy — which is a doubtful chayah and kilayim from behemah and chayah — must cover its blood and does not bless; and one does not slaughter them on Yom Tov; and if he slaughtered them he does not cover its blood; and at night, if its mark is recognizable, he may cover it.",
  "4#main": "Buffalo they practice not to cover its blood. {Rama: And some are uncertain regarding buffalo, that it is a wild ox — perhaps it is a chayah (Geonim and Arukh); therefore it is good to cover it without a blessing, or to slaughter a bird as well and then he can bless on the covering because of the bird (Hagahot Mahariu).}",
  "5#main": "There must be loose earth below and loose earth above; and he must designate it with his mouth; and some say he need not.",
  "6#main": "He covers with his hand, or with a knife, or with another vessel — but not with his foot, so mitzvot are not treated contemptuously.",
  "7#main": "If he slaughtered and there was no earth below, he must drag the blood and place it on loose earth and cover it with loose earth above.",
  "8#main": "The one who slaughtered covers; and if he did not cover and another saw it, the other is obligated to cover.",
  "9#main": "If he slaughtered one hundred chayot or one hundred birds, or slaughtered a chayah and bird in one place — one covering for all of them.",
  "10#main": "If one slaughtered and the blood was absorbed into the ground, if its mark is recognizable he must cover.",
  "11#main": "If the wind covered it he is exempt from covering; and if it became uncovered again he must cover; but if he himself covered it and it became uncovered he is not obligated to cover it a second time.",
  "12#main": "Blood that fell into water, or water that fell into blood — if it has the appearance of blood he must cover; if not, he is exempt.",
  "13#main": "If blood was mixed with red wine or with blood of behemah — we view the wine and blood of behemah as if they were water; and likewise if mixed with water, if in this measure it would have the appearance of blood he must cover.",
  "14#main": "If he slaughtered a bird or chayah and then slaughtered a behemah upon it — exempt from covering; but if he slaughtered a behemah and then slaughtered a chayah or bird upon it — obligated to cover. {Rama: If he slaughtered a bird or chayah and afterward slaughtered another and it became neveilah in his hand: if he knows the last one's blood covered the first's, exempt from covering; but stam (without such knowledge) he must cover (Hagahot Maimoniyot chapter 14, plain rule that he must cover, and he distinguishes if he knows etc., so these do not contradict the case of slaughtering behemah upon it where one is exempt).}",
  "15#main": "Blood that spurted and that is on the knife — if there is no other blood there except it, he must cover and drag it, so as to place earth also below; but if there is other blood there he need not cover that, for one need not cover all the blood; therefore one need not wait to cover until all the blood has come out. {Rama: However he should wait until drops begin to fall so he covers some of the lifeblood (Maharil in the name of Maharak, and ancient shechitot in the name of Maharash).}",
  "16#main": "One who slaughters for an ill person on Shabbat does not cover — even if he has a spit inserted. And at night, if its mark is recognizable, he may cover it. And some say that if he had ashes ready to cover with, feces — one may cover the blood with it even on Shabbat.",
  "17#main": "If one slaughtered and it became neveilah in his hand, or slaughtered and it was found to be treifah — exempt from covering; and likewise a deaf-mute, imbecile, and minor who slaughtered, and others do not see them — presumption is their shechitah is defective and exempt from covering.",
  "18#main": "One who slaughters even though he needs only the blood is obligated to cover. How should he act? He should kill by stabbing or uproot so as to be exempt from covering.",
  "19#main": "He must check the simanim and the knife before covering, so he does not come to a blessing in vain.",
  "20#main": "One who slaughters a chayah does not cover until he checks the lung; and if a safek treifah was found, he covers without a blessing. The same applies to every disqualification due to doubt — such as when we are concerned perhaps the hide was damaged; and all similar cases. {Rama: But something that by law is kosher, only they are stringent about it — such as if he cut the entire spinal column and similar — they are obligated to cover (Terumat HaDeshen siman 184).}",
  "21#main": "One who has no earth to cover should not slaughter. {Rama: Rather he should wait until he has earth (Tur); and if he travels in a desert or on a ship and the bird is not worth the loss of a garment he would burn to ash, or gold he would grind — the Sages enacted for him to slaughter and to absorb the blood in a garment or sandal, and bless; and when he reaches a place of earth he launders the garment or sandal so the blood comes out and covers without a blessing (Mordechai in the name of Geonim); and so is practiced (Or Zaru'a and Raavan).}",
  "22#main": "One who slaughters a chayah and bird and no blood came out from them — they are permitted.",
  "23#main": "All things in which seeds that are sown in them grow — they are included as earth and one may cover with them; and if they do not grow, if they are called earth one covers with them; therefore one covers with manure, and with very fine sand until a potter need not crush it at all, and with lime, with clay, with brick, with earthenware body that was crushed, with powdered stones, with powdered potsherds, with fine flax tow, with wood shavings, with burned food or garments until they become earth, with charcoal and coal blue, with refuse of mills — but one does not cover with manure that is still moist, nor with sand a potter must crush, nor with flour, bran, or middlings, nor with powdered metal if not burned — except ground gold which is called earth as written \"and dust of gold to him\"; and ashes are called earth as written \"and for the unclean they shall take of the dust of the burnt purification offering\" (Rambam end Hilchot Shechitah, chapter 14, daf 88b).}",
  "24#main": "One does not cover with desert dust because it is salty land and does not grow. {Rama: Therefore one does not cover with moist earth from water such as Mitoneta (Tur, Semak, Semag); and one does not cover with snow (Beit Yosef and Or Zaru'a in the name of a Gaon, not like Mordechai in the name of a Gaon).}"
});

// --- siftei-kohen (37) ---
patchFile('siman_028/siftei-kohen/part-001.txt', 'siftei-kohen', {
  "1#א": "[<b>Whether they were prepared in his hand.</b> Such as geese and chickens — for one might say from what is written \"that hunts\" it would exclude geese and chickens and similar that stand ready for hunting; therefore the verse teaches \"hunting\" in any case — end of his words.]",
  "1#ב": "[<b>And covering is a mitzvah in itself, etc.</b> See above siman 19 s.k. 6.]",
  "1#ג": "[<b>Kosher, etc.</b> It implies even for himself; and so Darkei Moshe; and so Beit Yosef and Maharshal, chapter Kisuy HaDam, siman 1, and other latter authorities — not like Bach who forbids for himself. However, where the people are lax in the mitzvah of covering — they do not cover properly, or do not bless on covering or on shechitah — one should penalize and obligate lashes; and also forbid shechitah to the transgressor because of erecting a fence; so appears from Maharshal's words there; and see above siman 19.]",
  "2#א": "[<b>On covering blood with earth, etc.</b> See above s.k. 29.]",
  "2#ב": "[<b>Recites shehecheyanu, etc.</b> Hagahot Minhagim that Darkei Moshe brought: covering is a mitzvah, as we say: in reward that Avraham said \"and I am dust and ashes\" his children merited two mitzvot — and one blesses shehecheyanu like tzitzit and sukkah, as explained in Hagahot Shechitot in the name of R' Yedidya of Shapiro — end of his words. And study is needed: regarding tzitzit we hold one does not bless shehecheyanu unless he acquired a new garment, because he acquired new utensils — as explained in Orach Chaim siman 223; but when making tzitzit on an old garment he does not bless shehecheyanu, as Ba'al HaItur, Mahari Abuhav, and Darkei Moshe in Orach Chaim siman 22 wrote; and so Shulchan Aruch and Levush there; and so appears in Tosafot, chapter Lulav and Aravah (Sukkah daf 46a), s.v. ha'oseh sukkah: the reason we do not bless shehecheyanu on tzitzit and tefillin is because shehecheyanu was enacted only for a mitzvah that has joy. And one can say regarding covering: since in reward for \"I am dust and ashes\" it is considered joy — on the contrary we say in chapter 25 (end of daf 88): Rava said in reward that Avraham said \"and I am dust and ashes\" his children merited two mitzvot — ashes of the red heifer and ashes of sotah; let us also count earth of kisuy hadam — there is no benefit in the mitzvah; and Rava said in reward \"if from a shoelace to a sandal strap\" they merited two mitzvot — tekhelet thread and tefillin strap — end; and so appears from Ran there: the reason we do not bless shehecheyanu on tefillin is because it does not come from time to time; and so Rashba in responsum 126. If so, all the more regarding covering. And it also appears: even for Rambam, chapter 1 of Hilchot Berachot, who blesses shehecheyanu on tzitzit and tefillin — it is because he wrote there: since they are mitzvot that are an acquisition for him — unlike covering. And I found in Rokeach siman 371: he wrote in the name of Rivash of Shapiro: any mitzvah incumbent on a person to do and he did not do it and is now beginning l'chatchila must bless shehecheyanu; and he brought proof from what we say in Menachot (daf 75): one standing and offering menachot in Jerusalem says shehecheyanu — I have become fit for service of the time — end; and perhaps on this they relied to bless on covering. But study is needed: if so, why do we not bless shehecheyanu on tzitzit, tefillin, and other mitzvot one begins? And likewise we do not bless shehecheyanu on kiddushin of a woman or her marriage, as Maharik wrote, shoresh 128; and likewise on mezuzah, as below siman 289. Rather, one must hold: even in a mitzvah one begins, one does not bless shehecheyanu unless its time is fixed — like Tosafot, Ran, and Rashba above; and our commentators explain that mishnah of offering menachot as Tosafot and Rashba in his chiddushim, chapter Keitzad Mevarchin: there were twenty-four watches and they did not renew more than twice a year; since they have a fixed time, one blesses shehecheyanu — end; if not so, not; and if so, the same regarding covering; and study is needed.]",
  "2#ג": "[<b>Because it harms a creature.</b> This reason is forced; in my humble opinion a more acceptable reason: shechitah is in his hand and he is not commanded to slaughter, for he can always be without meat or have another slaughter; but regarding covering, the obligation is placed on every person who sees blood to cover, as below seif 8.]",
  "3#א": "[<b>And kilayim from behemah and chayah, etc.</b> It deals with a gazelle that mounted a she-goat — we are uncertain whether we are concerned for the father's seed or not; therefore we are uncertain whether to cover and do not bless, lest we are not concerned — not like what is written in Sefer Zivchei Tzedek: the reason he does not bless is a decree lest he permit its milk and he was not precise; and study is needed. But if it were plain to us that we are concerned, he would be obligated to bless, for he must cover it from the Torah, for we hold gazelle and even partial gazelle; and regarding the mother's seed none disagree that plainly we are concerned; and see above siman 16 s.k. 17 from this.]",
  "3#ב": "[<b>And one does not slaughter them on Yom Tov.</b> Since he must cover them and on Yom Tov he may not cover them, he should not slaughter l'chatchila.]",
  "3#ג": "[<b>He does not cover its blood.</b> Even if he has earth prepared — because the observer will say: certainly it is a chayah, for otherwise they would not trouble to cover its blood on Yom Tov, and he will come to permit its milk — end; so Taz in Orach Chaim siman 498, seif 8; and this is the conclusion of the Talmud, first chapter of Beitzah (end of daf 8), and agreed by all poskim (and so Rashba wrote in Sefer Avodat HaKodesh, Beit HaMikdash, gate 2, law 2); and so Levush there — not like what Atzei Erez wrote here: one does not slaughter koy and kilayim on Yom Tov lest he move earth on Yom Tov not for a need, lest it be a species of behemah — end; and he was not precise, for even if there is prepared earth where there is no prohibition of moving, it is forbidden for the reason mentioned.]",
  "3#ד": "[<b>And at night if its mark is recognizable he may cover it.</b> And they cannot receive blood in a vessel to cover at night, for one does not slaughter into vessels — end; so Tur from Ra'osh and Ramban: forbidden because it appears as receiving blood for idolatry, as above siman 11, seif 3. And that they did not permit through placing a little earth in the vessel, as above siman 11 — because there too there is concern before the observer that he will say he took earth to cover and will come to permit its milk — so Derishah. But Bach wrote: and it appears to me that in our time (meaning there is no way of idolaters in this, as above siman 12, seif 12) that even l'chatchila one could slaughter into vessels like Or Zaru'a; only we are cautious) b'dieved if he slaughtered on Yom Tov he can receive blood in a vessel even l'chatchila, to fulfill kisuy hadam properly, and there is no prohibition by law to be cautious from receiving; nevertheless it is better to place earth and pebbles in the vessel before receiving — end; and in truth his words are difficult: why did the Talmud and poskim not teach us this enactment of earth in a vessel? Perhaps they only permit through a little earth in a case where one cannot say he will cover with it; and by law it would be forbidden since there is only a little earth, because of suspicion of idolatry that it is still fit for sprinkling; but nowadays when there is no way of idolaters in this, it is permitted even without earth at all; only stringently he should place a little earth — and examine well.]",
  "4#_": "<b>Or to slaughter a bird as well.</b> Next to the buffalo and not on the buffalo's blood, as below s.k. 24.",
  "5#_": "<b>And he must designate it with his mouth.</b> Meaning the earth below he must designate with his mouth for the purpose of covering where he found loose earth; otherwise he accomplishes nothing; and likewise when he places it for loose earth above it counts as designation — so appears from Rashi's explanation, chapter HaShochet (Chullin daf 31), and so in Agudah; and one authority holds: if he found loose earth and slaughtered upon it, that suffices; but earth above — all agree he must place it himself, as in Tosafot at the beginning of chapter 25; and so appears in Rabbenu Yerucham; and it appears they only disagree regarding the preferred mitzvah; but b'dieved it is plain for all he need not place it himself even for earth above, for \"the wind covered it\" in seif 11 exempts from covering — and it is a complete mishnah.",
  "6#_": "<b>Or with a knife.</b> Meaning in the groove of the knife; but not at the knife head where he slaughters, as above siman 18; and so Darkei Moshe and Perishah; and it is simple.",
  "8#_": "<b>The one who slaughtered covers, etc.</b> In Tur there are several laws regarding one who preceded and covered — what is he obligated; and the Mechaber wrote them in Choshen Mishpat siman 382, for that is their place — see there.",
  "9#_": "<b>He slaughtered one hundred chayot, etc.</b> And the law if he spoke between one covering and another, or between one shechitah and another, and similar laws — are explained in siman 19 — see there.",
  "12#_": "<b>Blood that fell, etc.</b> Even though it was nullified and the first was rejected, nevertheless when it went and increased until the appearance of water turned to blood, the first blood returns and is seen; and we do not say since it was rejected it remains rejected, for there is no law of rejection regarding mitzvot.",
  "13#א": "[<b>Or in blood of behemah or blood of chayah, etc.</b> So in the mishnah, daf 87, beginning of 87b; and Rashi, Ran, and Bertinoro: in blood of letting of chayah; and Rambam explained: in blood of an impure chayah.]",
  "13#ב": "[<b>We view, etc.</b> It appears to me the same applies if he slaughtered chayah or bird and blood fell into blood of behemah; and similarly in a case where if they had viewed behemah blood as water there would be no appearance of blood, and again more fell in — in a case where if it were water it would return and revive — he is obligated to cover.]",
  "14#א": "[<b>Exempt from covering.</b> For behold behemah blood is above — what will he cover? Rashi.]",
  "14#ב": "[<b>Or bird, etc.</b> And Bach wrote: with bird upon behemah exempt from covering, since bird blood is minimal — and it does not seem right; and what Maharshal wrote, chapter 25, siman 14, is not found — on the contrary Maharshal's words there appear the opposite; and what they forced to reconcile Beit Yosef's difficulty on Tur who wrote in the name of Ba'al HaItur — behold it is a complete baraita — his answer is forced — see there. What seems right: all poskim did not bring this baraita at all — it appears they hold we do not rule like this baraita, because Tosafot wondered on it: \"slaughtered chayah and afterward behemah — exempt from covering\" — say: let him drag it and cover it; and likewise behemah and afterward chayah — let him drag and cover, like blood that spurted and on the knife — end; and poskim hold to settle this wonder: this baraita holds that even for blood that spurted and on the knife one need not drag, only cover in place, as Maharam ben Natan wrote and Beit Yosef brought; if so, we who hold for blood that spurted and on the knife one must drag — we do not rule like this baraita; therefore Tur wrote this law in the name of Ba'al HaItur who holds this baraita is halakhah and must distinguish unlike blood that spurted and on the knife: here is different since behemah blood is above — what will he cover, as Rashi wrote — behold it is as if all mixed together; and likewise when chayah blood is above he is obligated to cover — the same: if there is loose earth below, as Atzei Erez and Levush wrote, page 193. Or: even if there is no loose earth below, perhaps he need not drag, because if he waits until he drags and it dries, chayah blood will mix with behemah blood; and before it dries plainly he cannot drag it and all will mix together; therefore better to cover in place. This is Tur's view; and perhaps poskim agree; and that they omitted this baraita is because it seemed plain; and this baraita was not brought in the Talmud except incidentally — see there.]",
  "14#ג": "[<b>Obligated to cover.</b> And even though there is no earth below between it and behemah blood — nevertheless whatever is possible we do; and Atzei Erez wrote here confused words.]",
  "16#_": "<b>And at night, etc.</b> See above s.k. 10 what is written on this.",
  "17#א": "[<b>And others do not see them, etc.</b> But when others see them — we say in the mishnah (daf 86a) he is obligated in covering; and it implies there in the Talmud he is obligated by law to cover; and so poskim; and so the law: among themselves they are exempt because most of their actions are defective; therefore when others see that they slaughtered well, since kosher even for eating, plainly they need covering and must bless; and so in Sefer Lechem, page 191, end of 191a — not like Atzei Erez who wrote he covers without blessing; however this is specifically when they are experts or know how to use their hands — then their shechitah is kosher b'dieved for all, as written in siman 1 s.k. 24; otherwise he covers without blessing; and see above siman 16 s.k. 21.]",
  "17#ב": "[<b>And exempt from covering.</b> In the Talmud it implies he may not cover, since most of their actions are defective and it is like full neveilah; when he covers, people will say the shechitah was excellent and they will err and eat from their shechitah — so Tosafot there, s.v. sippa, etc.; and so Bach.]",
  "19#_": "<b>He must check the simanim, etc.</b> See above siman 25 regarding checking simanim, and siman 18 regarding checking the knife.",
  "20#א": "[<b>Until he checks, etc.</b> And even though above siman 19 we say one blesses on shechitah before shechitah — that is because it is impossible otherwise, for all berachot one blesses before performing them, and we rely on the presumption that most animals are kosher, as below siman 81; but here, since it is possible to clarify, we clarify; and it is like above siman 1: we do not rely on presumption where we can clarify.]",
  "20#ב": "[<b>Such as when we are concerned perhaps damaged in the hide, etc.</b> And as above siman 18 s.k. 1 and 11; and Bach, section of Maharai, and the Mechaber, inferred from what Tur wrote in siman 18: if the knife was found defective after shechitah — behold it is neveilah, and he did not write safek neveilah; he comes to teach we establish it in full neveilah to exempt from covering, and one could say safek treifah — cover without blessing since the safek arose in shechitah itself — end. And one may wonder: how can it enter the mind to uproot a positive commandment from the Torah to exempt from covering because the knife was found defective — there is only a safek? And perhaps in the spinal column itself it was damaged — for there is an authority, first chapter of Chullin (daf 10), who validates; and although we rule stringently, nevertheless there is only a safek; and as we say in the Talmud: we are concerned perhaps damaged in the hide; and so all poskim wrote, as in siman 18. And what he inferred from Tur's words is nothing — certainly Tur in siman 18 did not come for this, for there he does not deal at all with laws of covering; and even if his intent were this, he would not write it in hint; and so in several places: \"this is neveilah\" is safek neveilah; and the Mechaber himself wrote in siman 18 \"this is neveilah.\" Also what he distinguished between safek treifah and safek in shechitah is not clear at all; and this is proven explicitly in the Talmud, chapter 25, daf 86, regarding shechitah of deaf-mute, imbecile, and minor: if not that most of their actions are defective, we would go stringently to require covering from safek — see there; and so Maharshal, chapter 25, siman 6, like the Mechaber; and so Darkei Moshe.]",
  "20#ג": "[<b>But something that, etc.</b> It implies that for cutting the spinal column he must cover by law and must bless; and so appears in Terumat HaDeshen; and so Sefer Lechem, page 191; and so logically: as written in siman 24 s.k. 5, that stringency in cutting the spinal column is stringency without reason; and I proved there from Talmud and poskim that it is permitted — see there; therefore although we are stringent to eat, because they already practiced so, plainly he must bless — not like Atzei Erez and Bach who wrote cover without blessing.]",
  "21#_": "<b>The Sages enacted for him, etc.</b> Beit Yosef rejected these words: if so, the tanna should have taught this enactment before \"burn his garment,\" for there is also bal tashchit; and further, since he does not cover with earth, how can he bless on it? Therefore it appears these words have no substance — end. And Rav in Darkei Moshe answered the first difficulty: the tanna deals when the bird equals the gold or garment he burns, and the Geonim deal when it does not equal; therefore it is impossible otherwise, and they made this enactment. And he did not answer the second: since when he absorbs blood in the garment it is the beginning of covering, and he can bless even though he does not complete covering until later — like checking chametz where we bless on bi'ur chametz although we do not burn until tomorrow (as explained in Orach Chaim siman 432); and the same here, etc.; and afterward I found in Or Zaru'a that he brought the Geonim's words and expanded on reasons and wrote one may rely on them — end Darkei Moshe; and so I found in Raavan who brought their words for halakhic ruling; and Maharshal, chapter 25, siman 17, followed Beit Yosef to reject the Geonim's words; and such rejection returns and appears wrong after it is explicit in great poskim mentioned; and their words are also settled — Maharshal himself brought the Geonim's words anonymously in his Hagahot to shechitot of Mahariu (indeed you will find several times in his book he retracts his first words). And so Bach. However what Darkei Moshe compared this law to checking chametz — I do not hold so: there the reason is checking is the beginning of bi'ur, and bi'ur is impossible without checking, and checking is tied to bi'ur — unlike here. It appears to me to add also the reason Bach wrote: the blessing was enacted only on covering blood, not on earth, as in Tosefta and Yerushalmi and poskim; and although we practice saying \"with earth,\" it is for ease of speech; but here we establish the law, and therefore when he absorbs in his garment one does not say \"with earth\"; and also in the Geonim's language it says \"he blesses on the covering\" and no more; and Atzei Erez wrote: it appears one should not bless l'chatchila when absorbing in his garment, nor afterward when laundering the garment; and had he seen Rav's words in Darkei Moshe he would not have written so.]",
  "22#_": "<b>The one who slaughters, etc.</b> It implies he comes to teach: although the mitzvah of covering was not fulfilled with them, they are permitted; and so Terumat HaDeshen, gate 5; and so Atzei Erez and Bach. But in the mishnah, chapter HaShochet (Chullin daf 33a), source of this law: \"one who slaughters behemah, chayah, and bird and no blood came from them — permitted\"; and since it mentions behemah, it implies it does not deal with covering; and so Rambam, chapter 4 of Hilchot Shechitah, law 13, in laws of dangerously ill: \"one who slaughters behemah, chayah, and bird and no blood came from them — behold they are permitted, and we do not say perhaps they were dying\"; and so explained in Sefer Torat Chaim and Mishmeret HaBayit, page 20: Rashba explained he comes to teach although no blood came from them they are permitted, for blood of limbs that did not separate is permitted, etc.; and see above siman 22.]",
  "23#א": "[<b>That are sown in them and grow, etc.</b> And it does not help when one places plants in them and they grow — rather we require specifically that seeds sown in them grow — Beit Yosef; and so Kol Bo in the name of Razah and Ba'al HaItur.]",
  "23#ב": "[<b>And with clay.</b> Meaning: in Arukh it is a type of lime they dig from the ground.]",
  "23#ג": "[<b>And from earthenware body that was crushed.</b> This crushing applies also to brick; and so is proven in chapter 25 — end Perishah. And Taz's words cannot be explained otherwise.]",
  "23#ד": "[<b>And with fine flax tow.</b> Rashi: this is areshta shaken from flax — and the same for earth. And shavings of pottery that carpenters plane in a plane and cut wood in it, and it leaves fine shavings like dust. Shichur — Rashi: ground charcoal; and so Arukh, entry shachor; and Rambam explained: soot of the kiln. Kocholet is dye put in the eye. Nekoret hapasulim — Rashi: dust scraped from millstones.]",
  "23#ה": "[<b>And not with powdered metal if they are not burned, etc.</b> But if burned one covers; and the same for all those one does not cover — if burned one covers with their ash — as in Tur and Beit Yosef; and it is simple.]",
  "24#א": "[<b>Therefore one does not cover, etc.</b> So in all books; and so Or Zaru'a translated; and it implies because moist earth does not grow — and it is not so, for in chapter Elu Overin (Pesachim daf 47) it is explicit it is fit for sowing and grows; and so Rashi there — although Beit Yosef translated Rashi's language \"not fit for sowing\" — plainly it is a scribal error; and Atzei Erez translated Beit Yosef's language and did not notice the error. But the reason is: we require fine earth fit to be counted, as written \"if a man can count the dust of the earth,\" etc.; and Beit Yosef and Darkei Moshe brought it; and it appears \"therefore\" is a scribal error and must read \"and so\"; and it is easy to understand.]",
  "24#ב": "[<b>With moist earth, etc.</b> And all the more with mud, as in the Talmud there.]"
});

// --- turei-zahav (19) ---
patchFile('siman_028/turei-zahav/part-001.txt', 'turei-zahav', {
  "1#א": "<b>Prepared in his hand.</b> For it is written \"that hunts\" — in any case; if so, why is \"hunts\" stated? The Torah teaches proper conduct: a person should not eat meat except with this preparation — so Rashi explains: as if it is hunting that is not prepared for him, meaning he should not eat meat frequently.",
  "1#ב": "<b>A mitzvah in itself.</b> And one can say from what Ra'osh wrote and Tur brought, siman 20: the mitzvah of covering completes the mitzvah of shechitah; in truth it is a mitzvah in itself, only related after the mitzvah of shechitah, like tefillin of the head with tefillin of the arm. And one should not challenge: why did Rama rule in Hagahah siman 19 seif 4 that one may speak between covering and shechitah — what is different from speaking between tefillin and tefillin? One can say: regarding tefillin the blessing of the head applies also to the arm, as we noted in laws of tefillin.",
  "2#_": "<b>Covering blood with earth.</b> Although we do not find anywhere mentioning the detail of the mitzvah in the blessing except generally — and it would suffice to say on covering blood alone — nevertheless here it is different, for one performs two mitzvot: covering below the blood and above; and this is learned from \"with earth\"; therefore one must say \"with earth\" to indicate the two mitzvot, as above; and see what is written siman 120 seif 3.",
  "3#_": "<b>From behemah and chayah.</b> This is also included in koy; and Rashal wrote: specifically when chayah mounted behemah we say one does not slaughter on Yom Tov, since we are uncertain whether we are concerned for the father's seed and perhaps we are not concerned; but when behemah mounted chayah he must cover certainly, and there is no safek — for gazelle and even partial gazelle we say, as we said above siman 17 seif 8: sheep even partial sheep; and therefore one slaughters it on Yom Tov; and so explicit in the Gemara, chapter Oto Va'et Beno, conclusion of Rav Pappa: when a ram mounted a she-gazelle he must cover certainly, for gazelle and even partial gazelle we say; and you find safek only in gazelle mounting she-goat, where there is safek whether we are concerned for father's seed and it would be partial gazelle; and although Tur, Rambam, and Shulchan Aruch wrote here plainly \"from behemah and chayah,\" they relied on what is written in Oto Va'et Beno that sheep even partial sheep — here too; and therefore explain it deals with gazelle mounting she-goat; and in Perishah he also challenged from here on Oto Va'et Beno and answered: regarding Oto Va'et Beno Scripture revealed sheep even partial sheep, but here Scripture did not reveal — there is room to doubt perhaps only for full chayah is covering required — end; and he did not examine the Gemara we cited that is explicit for one who holds sheep even partial sheep also holds even partial gazelle for covering — he is obligated; and Maharach wrote: Tur holds like \"some say\" later in the Gemara in the baraita of koy: it is from she-goat and gazelle; and this \"some say\" does not hold we say even partial gazelle, although regarding sheep we say so. I cannot rest on this either, for certainly Rav Pappa who said in the conclusion that you find regarding covering only gazelle mounting she-goat saw and knew this baraita of \"some say,\" and nevertheless explains it does not deal with ram mounting she-gazelle; for otherwise Rav Pappa would argue on the baraita from reasoning — and so is proven from what they said in the Gemara before: \"koy — one does not slaughter on Yom Tov — what are we dealing with?\" If you say ram mounting she-gazelle — whether according to Rabbanan or R' Eliezer — to slaughter and cover gazelle and even partial gazelle, etc.; since they challenge plainly thus, it implies it is plain they equate sheep even partial sheep with gazelle even partial gazelle; rather the clear truth is Rashal's view I cited.",
  "4#_": "<b>To slaughter a bird as well, etc.</b> Meaning: he slaughters the bird next to it, but not mixed with buffalo blood, for it would be nullified in it, as written in seif 13 regarding blood of chayah mixed with blood of behemah if mixed in water, etc.",
  "5#_": "<b>Loose earth below, etc.</b> For it is written \"with earth\" — teaches that two coverings are required.",
  "6#_": "<b>With a knife.</b> Meaning in the groove of the knife, but not at its head lest he damage it.",
  "8#_": "<b>Obligated to cover.</b> In the Gemara they derive from what is written \"and say to Bnei Yisrael\" — a warning to all Bnei Yisrael; and Tur concludes here: obligated to cover, for the mitzvah of covering is like other positive commandments incumbent on all Israel, only the slaughterer precedes everyone; therefore if another preceded and covered, he must give him ten gold pieces — wages for the blessing he prevented from him — end. And it is difficult: why did he need to give an additional reason beyond the derivation from the verse in the Gemara? Also the language \"therefore\" is not well settled — he should have said \"and if another preceded,\" etc. It appears his intent: lest we err and say since the Torah said \"and pour out and cover\" — whoever pours covers — and afterward said a warning to all Israel, we must say the warning is when he is not there; but if he is there, another is not included in the warning; if so, if another wants to cover while the slaughterer is there, he does not bless, since he is not warned about this act; accordingly he has no obligation to pay ten gold — for one pays blessing wages only when he benefits and prevents his fellow from it; unlike here where he does not benefit, only prevents his fellow's benefit of the blessing and harms him generally. Therefore Tur wrote the mitzvah of covering is like other mitzvot — meaning: since the verse revealed a warning on all Israel, here it is like all mitzvot incumbent on all Israel even if he is there, only the slaughterer comes first in that obligation; therefore since in any case there is warning even when he is there, he blesses properly; and since he blesses and prevents his fellow the benefit of the blessing, he must give ten gold as above. Tur wrote: however they do not collect this nowadays, for it is like penalty laws, as explained in Choshen Mishpat siman 1; therefore Shulchan Aruch did not bring it; but I saw in Semak that he wrote: nevertheless he did not act well and must appease him.",
  "12#_": "<b>Into the water.</b> He explained: we do not say the first is nullified, for there is no rejection regarding mitzvot.",
  "14#א": "<b>He slaughtered bird, etc.</b> Tur wrote this law in the name of Ba'al HaItur; Beit Yosef wondered: behold this law is a baraita in chapter Kisuy HaDam; it appears he learned from it — since Ba'al HaItur in Tur mentioned first exemption of bird or chayah and in the obligation part mentioned only chayah, not as Shulchan Aruch translated here. Certainly Ba'al HaItur's intent: when slaughtering bird upon behemah there is no covering because its blood is minimal; and so I saw Rashal wrote — and it did not settle for me: are all birds equal or all behemot equal? Explicitly in Sotah (daf 16): regarding bird blood mixed in water, not all birds are equal; and here everything depends on the measure if there was water, as seif 13; and Tur's intent appears thus. One can challenge the reverse: why did Rif, Ra'osh, and Rashba in Torat HaBayit not bring this law of slaughtered chayah and afterward behemah, etc., or the reverse, since explicit in the baraita? It appears their intent: in the baraita Rabbi Yonatan ben Yosef says: slaughtered chayah and afterward behemah, etc.; since it teaches \"Rabbi Yonatan says,\" the first tanna disagrees and holds one is not obligated even when slaughtering chayah upon behemah, since there is no earth below under chayah blood; or vice versa: even slaughtering behemah upon chayah there is covering — he drags behemah blood and covers chayah blood, as Tosafot challenged on Rabbi Yonatan ben Yosef; therefore Rif and Ra'osh did not bring Rabbi Yonatan's words, since many disagree with him; and Ba'al HaItur holds halakhah is like Rabbi Yonatan; therefore Tur brought this law in Ba'al HaItur's name — clear and correct.",
  "14#ב": "<b>Obligated to cover.</b> Meaning: as it is; and even though there is no earth below under chayah blood, nevertheless that suffices; and Tur explains the reason in the Gemara: since nevertheless it would have been fit initially to place earth below, and whatever is fit for mixing — mixing does not block it. Tosafot challenged: why not drag it and cover with earth below like blood that spurted in seif 15? And they conclude in astonishment; and Levush wrote on this he must cover provided there is loose earth below that will be absorbed in the end; and if no loose earth below he drags it all as it is and places loose earth below and above, etc. — all this is a great error and he did not examine the Gemara at all, only wrote from his own mind erroneous things.",
  "14#ג": "<b>And it became neveilah in his hand.</b> Beit Yosef wrote this law in Hagahot Maimoniyot in the name of Maharam: obligated to cover; and Beit Yosef challenged what is written regarding slaughtering behemah upon chayah that one is exempt from covering. Rama answered here: it deals when he does not know whether the last blood covered the first; we do not say stam it did not cover it, and therefore he must cover. And one may wonder: how can such a rule be given to obligate a blessing stam — are all chayot or birds equal to one another? In my humble opinion another way (Rambam) [Maharam] wrote this law specifically when it became neveilah in his hand: the reason — whatever left in the second bird's shechitah before it became neveilah is blood fit for covering, and at that time it is called shechitah blood; and although after it became neveilah retroactively it is blood unfit for covering, nevertheless it was already nullified when it had a name fit to cover; with this we do not follow the measure whether in water there would be appearance of blood, but this blood was nullified in the blood that was there first. One can compare this to moist chametz mixed before Pesach in wine, for we hold it does not return and revive, as in Orach Chaim siman 467, since at the time of mixture it had a name of permission; so here too initially it had a name of permission. Therefore Maharam said properly: stam when he sees it became neveilah he throws it from his hand immediately — if so, there is no blood for the lower to nullify; but if it already became neveilah at the beginning of shechitah and he continues slaughtering and extracting blood, certainly one does not bless on this covering as long as we have not clarified there is so much that if mixed in water there would be appearance of forbidden blood, as seif 13 — in my humble opinion clear.",
  "16#_": "<b>Even if he has a spit inserted.</b> Although it is only rabbinically forbidden, we do not say: since he slaughtered with permission he may cover, as on Yom Tov where the Sages wanted to make a distinction that it is a day forbidden for shechitah; therefore they only permitted what the ill person needs — so Ran wrote.",
  "17#_": "<b>And likewise deaf-mute, imbecile, and minor.</b> It appears the same applies to an adult who slaughtered and does not know laws of shechitah — most of his actions are defective; and see siman 16 s.k. 13.",
  "19#_": "<b>So he does not come to a blessing in vain.</b> Meaning: if a disqualification is found in the simanim there is no covering at all; and if the knife is found defective, although he must cover from safek that perhaps the spinal column was damaged, as written afterward — nevertheless in both there is no obligation of blessing; therefore he should not cover before checking simanim and knife. And one can ask: why do we bless the shechitah blessing before shechitah lest treifah be found — for we require the blessing precede the act; and even though for netilat yadayim and immersion we bless after the act — there it is different, for otherwise impossible, as a person is not fit, as in siman 4 seif 1; here we rely on the majority that are kosher. In Derishah he wrote in the name of Rashal: the shechitah blessing is different — it helps purify from neveilah status immediately. And it is astonishing: if so, why did they say regarding one who slaughters where a defect arose — slaughter without blessing, as in siman 19 seif 1? If it purifies from neveilah, etc. Rather one must hold we only bless on what is permitted to eat from it.",
  "20#_": "<b>All the spinal column, etc.</b> Specifically in this stringency that by law is completely kosher even for us, as we noted siman 24 seif 4 — it is a general mitzvah; therefore cover with blessing.",
  "21#_": "<b>The Sages enacted for him, etc.</b> Beit Yosef brought Mordechai's words in the name of Geonim and challenged them: if so, the tanna should have taught this enactment before what he taught about burning gold; and further, how can he bless on covering with earth — behold he does not cover with earth, only absorbs in his garment? Therefore he wrote these words have no substance. Rama in Darkei Moshe answered the first difficulty: the tanna deals when the bird equals the gold or garment burned, and Geonim deal when it does not equal; therefore impossible otherwise, and they made this enactment. He did not answer the second: since when absorbing blood in the garment it is the beginning of covering and he can bless although he does not complete covering until later — like checking chametz, etc. This too is nothing: unlike bi'ur chametz where bi'ur is impossible without checking first, so at the time they commanded bi'ur, checking was included; unlike here where no man does so — only this person because he has no earth; certainly one cannot say this is included in the original command; on the contrary one should say he should not slaughter at all since he has no earth to cover. Maharach answered the second difficulty: one does not bless on covering blood with earth, but bless on covering the blood, as in Tosefta — the essence of the blessing formula is so; and study is needed: even so, we require covering be with earth as explicit in the verse \"and cover it with earth,\" only need not mention it; as I noted above seif 2 in the question. Therefore it appears clear we should not practice this enactment; and so I saw Rashal in his book, chapter Kisuy HaDam, siman 17: it appears these words have no substance; although Or Zaru'a brought them, if it were truly Geonim's words, Rif or Rambam would not have omitted them — end. And Levush also wrote one does not bless on this covering, neither at the beginning nor end — implying he was only strict about blessing, but the essence of covering one may do; and I say: one who has no earth to cover should not slaughter at all, since this enactment does not exist, as Tur and Shulchan Aruch wrote here — in my humble opinion clear.",
  "23#א": "<b>That are sown in them and grow.</b> Meaning: not earth that grows grass already grown.",
  "23#ב": "<b>And with clay.</b> It is a type of lime and needs no crushing — Beit Yosef. And from earthenware body that was crushed — this crushing applies also to brick. And with flax tow — meaning shaken from flax. And wood shavings of carpenters' plane. Shichur — ground charcoal; nekoret hapasulim — dust from millstones."
});

// --- baer-heitev (25) ---
patchFile('siman_028/baer-heitev/part-001.txt', 'baer-heitev', {
  "1#_": "<b>Covered.</b> And so Taz wrote: although Ra'osh wrote the mitzvah of covering completes shechitah — one must say in truth it is a mitzvah in itself, only related after shechitah like head tefillin after arm tefillin. And one should not challenge why Rama ruled in Hagahah siman 19 that if he spoke between shechitah and covering it is kosher — unlike speaking between tefillin and tefillin; one must say regarding tefillin the head blessing applies also to the arm, unlike shechitah and covering; from \"kosher\" stam it implies even for himself. And Bach forbids for himself — from Maharam.",
  "2#_": "<b>To a creature.</b> And Shach wrote another reason: because shechitah is in his hand and he is not commanded to slaughter, for he can always be without meat or have another slaughter; but regarding covering the obligation is on every person who sees blood to cover, as below seif 8. However study is needed why we bless on covering more than shehecheyanu on tefillin, mezuzah, kiddushin, or other mitzvot one begins; he left it in study; and Peri Chadash ruled not to bless shehecheyanu — safek berachot lehakel. And Taz wrote: that one must say on covering blood \"with earth\" and not say plainly on covering blood — because here one performs two coverings below and above, learned from \"with earth\"; therefore must say \"with earth\" to indicate two mitzvot; and see siman 120 seif 3.",
  "3#א": "<b>Yom Tov.</b> The reason: because covering is required and on Yom Tov he may not cover them. And Taz and Shach: that he does not bless on kilayim from behemah and chayah deals with gazelle mounting she-goat, since we are uncertain whether we are concerned for father's seed; but behemah mounting chayah he must cover certainly and there is no safek and must bless — for gazelle and even partial gazelle we say; regarding mother's seed none disagree that plainly we are concerned, as we said above siman 16 — Shach.",
  "3#ב": "<b>Its blood.</b> Shach wrote: even if there is prepared earth — because the observer will say certainly it is chayah, for otherwise they would not trouble to cover on Yom Tov and will come to permit its milk.",
  "3#ג": "<b>He may cover it.</b> Shach wrote: nowadays on Yom Tov one may place a little earth in a vessel and receive blood into it until night. That regarding koy we require covering from safek — unlike other safekot; see responsum of Maharam of Lublin siman 65.",
  "4#_": "<b>The bird.</b> Shach explains: he slaughters the bird next to the buffalo, not on the buffalo's blood, for it would be nullified, as in seif 13 in mixture of chayah blood with behemah blood, etc. * Study is needed: in siman 297 seif 6 he wrote plainly wild ox is a species of behemah.",
  "5#_": "<b>Required.</b> Meaning: if he found loose earth he slaughters upon it and that suffices. Shach wrote: but earth above — all agree l'chatchila he must place it himself; b'dieved kosher even if he did not place earth above, for \"the wind covered it\" exempts, as below seif 11. Hagahot Issur VeHeter wrote: now they practice to take kiln ash, place on the ground, make a pit, lower bird blood, check simanim and knife immediately, then cover with a scoop of ash.",
  "6#_": "<b>With a knife.</b> Meaning in the groove of the knife, but not at the head lest he damage it.",
  "8#_": "<b>To cover.</b> See Choshen Mishpat siman 382 regarding one who preceded and covered — what he owes.",
  "12#_": "<b>To cover.</b> Taz wrote: we do not say the first is nullified; and although rejected, it is rejected — for there is no rejection regarding mitzvot.",
  "13#_": "<b>To cover.</b> Shach wrote: it appears to me the same if he slaughtered chayah or bird and blood fell into behemah blood — in a case where if they viewed behemah blood as water there would be no appearance of blood, and again more fell in — in a case where if water it would return and revive — obligated to cover without blessing; and so Pri Chadash wrote.",
  "14#א": "<b>To cover.</b> Shach wrote: and even though there is no loose earth below, whatever is possible we do. Taz wrote the reason: since nevertheless it would have been fit initially to place earth below, and whatever is fit for mixing is not blocked. Tosafot challenged why not drag and cover with earth below like blood that spurted in seif 15 — and they conclude in astonishment. Bach wrote: with bird upon behemah exempt from covering because bird blood is minimal; Taz and Shach disagree — everything depends on the measure if there was water, as seif 13.",
  "14#ב": "<b>To cover.</b> Taz disagrees with Rama who wrote stam he must cover — how can such a rule obligate blessing stam? The essence depends: if initially blood left before it became neveilah, although afterward retroactively unfit blood, it was already nullified; compare to moist chametz mixed before Pesach — does not return and revive since at mixture it had permission; but if already neveilah at start of shechitah while continuing — certainly no blessing on this covering until clarified there is enough that in water would show blood, as seif 13 — clear, end.",
  "16#א": "<b>Inserted.</b> Taz wrote: although only rabbinically forbidden, we do not say since slaughtered with permission he may cover like Yom Tov where Sages wanted a distinction that slaughter is forbidden; they only permitted what the ill needs. And according to one authority who permitted if ready to cover with feces — nevertheless what they kindle on Yom Tov is forbidden to cover with that ash unless fit to roast an egg — see Orach Chaim siman 498 (Maharam).",
  "16#ב": "<b>He may cover it.</b> See end of seif 3 what I wrote there in the name of Shach.",
  "17#_": "<b>From covering.</b> \"And a minor\" — the same applies to an adult. Shach wrote: in the Talmud it rules forbidden to cover so they will not say certainly excellent shechitah; but when others see them, plainly their shechitah is kosher and must cover and bless; all this specifically when experts or know how to use their hands — then kosher b'dieved for all; otherwise cover without blessing.",
  "19#_": "<b>In vain.</b> Shach wrote: but shechitah blessing cannot be recited, since one must bless before performing and we rely on presumption most animals are kosher; but here, since possible to clarify, we do not rely on presumption where we can clarify; see siman 1.",
  "20#א": "<b>In this.</b> Bach disagrees with Mechaber and ruled: if safek found — what is exempt from covering; Taz disagrees and agreed with Mechaber; and so Maharshal.",
  "20#ב": "<b>To cover.</b> Shach wrote: must bless — not like Bach who rules cover without blessing. Likewise shehiyah, darsah, haladah, hagramah in minority in simanim — must cover with blessing (Shach). One who slaughters for dogs or for idolaters' eating — must cover. Minhag in the name of Shach.",
  "21#א": "<b>He will burn.</b> Pri To'ar wondered: why must he burn his garment — when he burns the garment he has fire; if so he can cover with ash of that fire, or cook or roast the bird and thus he has fire — see there.",
  "21#ב": "<b>Practiced.</b> Shach wrote: in any case when blessing one does not say on covering blood \"with earth,\" only on covering blood; Taz disagrees with Rama's gloss and ruled like Mechaber: one without earth to cover should not slaughter; Peri Chadash concludes he has no remedy except burn garment or grind gold dinars; Sefer Nehora disagrees with Taz and rules like Rama.",
  "22#_": "<b>Permitted.</b> Meaning: although mitzvah of covering was not fulfilled, they are permitted; and likewise behemah from which no blood came — permitted, for blood of limbs that did not separate is permitted.",
  "23#א": "<b>In them.</b> Shach wrote: it does not help when one places plants and they grow — rather we require specifically seeds sown in them grow.",
  "23#ב": "<b>Burned.</b> Shach wrote: but if burned one covers; and the same for all those one does not cover — if burned one covers with their ash. One does not cover with sulfur and salt, nor ground pepper; but with ground cinnamon one covers (Minhag in the name of Shach).",
  "24#_": "<b>Moist.</b> Shach wrote: it implies here moist earth does not grow — and this is not so, for in chapter Elu Overin (Pesachim daf 46) explicit it is fit for sowing and grows; rather the reason we do not cover with moist earth is we require fine earth fit to be counted, as written \"if a man can count the dust of the earth,\" etc.; therefore it appears \"therefore\" that Rama wrote is a scribal error and must read \"and so.\" Rambam end Hilchot Shechitah: permitted to cover with dust of an ir hanidachat; and the same with dust of idolatry and other issurei hana'ah, because mitzvot were not given for benefit (Maharam)."
});

// --- beer-hagolah (24) ---
patchFile('siman_028/beer-hagolah/part-001.txt', 'beer-hagolah', {
  "1#_": "Mishnah Chullin daf 83.",
  "2#_": "Tur in the name of his father the Ra'osh there: covering is a mitzvah in itself; and so Rambam chapter 14 of Hilchot Shechitah.",
  "3#_": "There in the mishnah.",
  "4#_": "Like Rabbi Yossi in the baraita there, daf 87.",
  "5#_": "Like one authority there.",
  "6#_": "Tur in the name of his father the Ra'osh.",
  "7#_": "The Ra'osh there.",
  "8#_": "So Tur explains from the baraita \"one who slaughters and it was absorbed,\" etc., daf 87; and so Rashba in Torat HaBayit.",
  "9#_": "In Hagahot Agur in the name of R' Yitzchak.",
  "10#_": "Statement of Rabbi Zeira there, daf 83.",
  "11#_": "Tur (and Kol Bo) in the name of Ba'al HaItur, and as Rashi explains.",
  "12#_": "There in the name of the Ra'osh at the end of the chapter; and so Tosafot here (and Agur wrote that so is practiced).",
  "13#_": "Baraita Chullin daf 86.",
  "14#_": "Tur from what they challenge in Kodshim: drag it and cover it — there daf 83; and so Rashba in Torat HaBayit.",
  "15#_": "Baraita there daf 87.",
  "16#_": "Mishnah there.",
  "17#_": "Mishnah there daf 86, and as Tosefta Kifshuta.",
  "18#_": "Baraita and Gemara there daf 87.",
  "19#_": "Mishnah there, and as established by Rabbah bar bar Chana, etc.",
  "20#_": "Mishnah there, and as Rav Pappa there: there is no rejection (dichui) regarding mitzvot, and we do not say the first is nullified.",
  "21#_": "There in the mishnah.",
  "22#_": "Baraita there daf 83.",
  "23#_": "Mishnah there, and we rule like Tosefta Kifshuta of the mishnah, and as Rabbi Yehudah explains according to it.",
  "24#_": "Ran there; and so Rashba in Torat HaBayit; and Beit Yosef according to Tur and Tosafot."
});

// --- beur-hagra (33) ---
patchFile('siman_028/beur-hagra/part-001.txt', 'beur-hagra', {
  "1#א": "<b>Whether, etc.</b> Mishnah and Gemara there.",
  "1#ב": "<b>And covering, etc.</b> From what is written (there 87b and conclusion) regarding koy: one does not slaughter it on Yom Tov, and if slaughtered one does not cover its blood, even with inserted spit that does not block rejoicing of Yom Tov; and Rashi in first chapter of Yom Tov 5:2, s.v. ein maksin oto b'yom tov, etc.",
  "2#א": "<b>Obligated to bless before, etc.</b> As written (Pesachim 7b and conclusion): all mitzvot one blesses before performing them; and in Tosefta last chapter of Berachot and Yerushalmi there: the slaughterer needs a blessing for himself on shechitah, and the one who covers needs a blessing for himself on kisuy dam.",
  "2#ב": "<b>One who slaughtered, etc.</b> As written at the end of chapter Kisuy HaDam: in reward that Avraham said \"and I,\" etc.; and in reward Avraham said \"if,\" etc.; and they bless as they bless on all mitzvot — tzitzit, sukkah; and Orach Chaim siman 23; and Shach here.",
  "3#_": "<b>And at night, etc.</b> As written there 87a: one who slaughters and blood was absorbed, etc. (and in Tosefta 6: one who slaughters on Shabbat, etc.).",
  "4#א": "<b>Buffalo, etc.</b> As they explained that it is re'em.",
  "4#ב": "<b>And some are uncertain.</b> They call it koy in foreign tongue. (Likut) Buffalo, etc., and some, etc.: they disagree whether it is wild ox or wild ram; and see siman 297 (s.k. 14; and Maharshal's difficulty there s.k. 5 is resolved according to the Rav, but in their sources it appears the uncertain ones' view as our master wrote in Likut 2, and so the Rav's language \"and some, etc., that it is wild ox,\" etc.). (Likut) Buffalo, etc.: and it is wild ox over which R' Yossi and Tanna Kamma disagree and we rule like Tanna Kamma; and so Rambam. And some: Mordechai siman 494 in the name of R' Chananel in the name of Geonim — their reasons appear (they are uncertain lest halakhah is like R' Yossi) because R' Eliezer in Chullin chapter 1 holds like R' Yossi; and Tosafot there s.v. vedilma, etc., and Ra'osh there (and see siman 80 s.k. 78). (Likut) Tosafot Zevachim 113b s.v. orzila; and those buffaloes, etc. — end.",
  "5#_": "<b>And required, etc.</b> Rashi there 31a, s.v. demazmin, etc.; and Tosafot there 87b, s.v. tzarich, etc.",
  "14#_": "<b>He slaughtered bird or chayah, etc.</b> In Pri To'ar he contradicts this, for in the Gemara they said slaughtered chayah and afterward behemah — exempt from covering, as above; and it implies even stam; and what they challenged on Gemara's words is not difficult, for there it deals when they were mixed — see there.",
  "15#א": "(Likut) If there is no, etc. As written in chapter 3 of Sanhedrin and end of chapter 7 of Eruvin; and although Rami bar Chama holds when to divide we rule like Ribbi and R' Yochanan; and although we say here three disputes in the matter — meaning Tanna Kamma of the baraita specifically in our mishnah to explain; and we rule like the mishnah; and see what Tanna Kamma holds is Tanna Kamma of Rashbag; and especially in our version we learn in Tanna Kamma of Rashbag: teaches that all its blood, etc.; but R' Yossi comes to explain even in the baraita. Tosafot and Ra'osh there and conclusion. But sugya of Gittin 7:8 \"when to divide\" and Tosafot there s.v. amar, etc. — end.",
  "15#ב": "(Likut) And he drags it, etc. 87b: and let him drag it, etc. — evidently he drags. Torat HaBayit. And Ra'ah disagreed, and likewise on what is written in siman 7 \"slaughtered and did not,\" etc., that he learned from here; and wrote: what \"evidently he drags\" means applies only to the end and on the knife, because its end will be removed from there; but for blood that spurted — not required; and as Shach wrote: was it not taught, etc.; and with this Tosafot's difficulty there s.v. shachat, etc., is resolved; and it appears from those Tosafot they hold like Torat HaBayit that whatever can be dragged should be dragged even if not me'akev; and in Rashi's words there s.v. kol hara'uy, etc., \"and the same 'fit',\" etc. — resolves Tosafot's difficulty; they hold there is no need to drag except before he slaughtered it was fit, only that in the case of blood, etc., meaning the difficulty is on the knife; and from Rif, Rambam, and Ra'osh who are silent it appears they hold like Ra'ah; and on the knife they did not need to explain that plainly he drags it, as Rashi wrote in s.v. hanichud — end.",
  "15#ג": "<b>However he should wait, etc.</b> As written there Rashbag: in another case, etc.; and even though they disagree on him — meaning not all lifeblood is required.",
  "16#א": "<b>Even if, etc.</b> For if not so, it would not enter Rav Eina's mind to permit — it is not better than Yom Tov.",
  "16#ב": "<b>And at night, etc.</b> As Shach wrote 87a \"one who slaughters,\" etc.; and likewise (s.k. 60).",
  "16#ג": "<b>And some say, etc.</b> Although regarding koy one does not cover even in such a case there because of permitting its milk — unlike here. (Likut) Even if, etc.: from what Shach wrote \"covering that is not certain,\" etc. — safek issur even in such a case, as in first chapter of Yom Tov (8); and Tosafot there s.v. kisuy, etc.; and for the language \"because of permitting its milk,\" etc. And some, etc.: and so Ra'ah wrote, only he wrote even for koy on Yom Tov the law is so, and we do not rule (so) as in Orach Chaim siman 498 seif 8, and so in the Gemara there they challenge from \"one does not slaughter,\" etc.; \"if so,\" etc.; rather Rava said kiln ash; and so Rav Yehudah; and so Rashi there s.v. ve'ein da'ato, etc.; Rami son of R' Yossi: do not say kiln ash was his intent, etc.; and Rav Yehudah — rather prepared earth for all; only because of permitting milk; and so in Maharshal; and here he was uncertain and expanded there and concluded one never covers — baraita teaches plainly; and so Rava who said it is a disgrace, etc.; and so those Tosafot; and so essence of what Shach wrote \"covering that is not certain\" — evidently one law for them — end.",
  "19#_": "<b>Required, etc.</b> As in Yerushalmi (chapter 9 of Berachot): when does one bless on shechitah? R' Yossi says before shechitah; Yossi ben Nahorai says after he slaughtered — lest the shechitah become neveilah; and although we do not rule thus and are not concerned for this — here, since possible, I am cautious; and Shach.",
  "20#א": "<b>One who slaughters chayah, etc.</b> And although we say in Yerushalmi: from now when he checks, presumption of innards is kosher — nevertheless here we do not rely l'chatchila, as above.",
  "20#ב": "<b>And if found, etc., and the same for all, etc.</b> As regarding koy: obligated in covering from safek; and likewise deaf-mute, imbecile, minor — Rabbanan obligate in covering; and even R' Meir only disagrees because most of their actions are defective; but in half and half — no. (Likut) And if found, etc.: as Shach wrote 86a \"for Rabbanan stringently\" — end.",
  "21#א": "<b>One who has no, etc.</b> So in the baraita there 88b: one traveling in the desert, etc. (Likut) One who has no, etc.: from mishnah 87b \"and one does not slaughter,\" etc.; and first chapter of Yom Tov 5:1 \"if so, what is different,\" etc. — \"not necessary\" he says, etc.; and there 2 (1 in mishnah) \"and in a boat,\" etc.; and Chullin 31a \"and behold covering is required,\" etc. — end.",
  "21#ב": "<b>As loss, etc.</b> There in the baraita.",
  "21#ג": "<b>They enacted, etc.</b> Because of bal tashchit; and that they said in the Gemara this enactment of burning, etc. — there when it equals, then there is no bal tashchit, as in chapter HaChovel (Bava Kamma 91b): if worth more for building, permitted to cut — and so Rambam Hilchot Melachim chapter 6 (and Semag lavin 129); and that he blesses — since when he absorbs in the garment it is beginning of covering although he does not complete until later. This enactment of Geonim is forbidden when possible through the Gemara's enactment; therefore they did not teach there this enactment of Geonim; and this is what \"and not equal,\" etc. — specifically in such a case — Darkei Moshe.",
  "21#ד": "<b>And bless, etc.</b> And although he has not yet fulfilled covering — like on checking chametz we bless on bi'ur, as Ra'osh wrote (chapter 1 of Pesachim siman 10): the beginning of burning is it.",
  "21#ה": "<b>He launders, etc.</b> As written (87a): blood mixed in water if there is appearance, etc.",
  "23#א": "<b>All things, etc.</b> Tosafot there s.v. kol davar, etc.",
  "23#ב": "<b>And if they do not, etc.</b> See there s.v. shachak, etc.; and although not, etc.",
  "23#ג": "<b>And with very fine sand, etc.</b> For in cooked Torah one follows the stringent — as in first chapter of Avodah Zarah (7a); and Ba'al HaGadol; and it is Rif's explanation; and for Rashi — latter wording.",
  "23#ד": "<b>And with powdered stones, etc.</b> Baraita there.",
  "23#ה": "<b>And with food or garments, etc.</b> Burned food there — Sages taught: one does not cover, etc., as it says \"and they shall take,\" etc. Burned garments there: burn his garment, etc.; and Tosafot there s.v. matzinu, etc.",
  "23#ו": "<b>And with shichur, etc.</b> There the tanna added, etc.",
  "23#ז": "<b>And not with powdered metal if, etc.</b> Tosafot there s.v. shchikat, etc.; and Rabbenu Tam answered, etc.",
  "23#ח": "<b>Except, etc.</b> Gemara there; and Tosafot there s.v. shochak, etc.; and above where it said one does not cover, etc.",
  "24#א": "<b>Therefore, etc.</b> End of chapter 3 of Pesachim (47b).",
  "24#ב": "<b>And one does not, etc.</b> Not like the Gaon wrote to cover with snow, as written (Iyov 37:6) \"for to snow He says 'Be earth'\" — for it is not written \"Be dust\"; and further: the Holy One commanded it should be on earth — for it is not written it should be called earth; and also when it melts and warms it is water, and one covers with water."
});

// --- kereti (29) ---
patchFile('siman_028/kereti/part-001.txt', 'kereti', {
  "1#_": "Even if he acted willfully; even for one who acted willfully — so many latter authorities, not like Bach.",
  "2#א": "Blood with earth — so they raised and so they practiced: although they cover with other things, all are offspring of earth and return to earth; and in Scripture it says \"and cover it with earth.\"",
  "2#ב": "Shehecheyanu — and Shach argued: many mitzvot like tefillin and tzitzit — we only bless when specifically required, or mitzvah with joy, or coming from time to time — unlike covering. It appears: mitzvot where obligation is placed on a person to do, like tzitzit and tefillin — one does not bless shehecheyanu; and although for tzitzit if he lacks four corners he is not obligated, nevertheless at the time of wrath he is punished; but he is not obligated to procure himself to slaughter and cover — most of Israel do not slaughter and cover; therefore if such a mitzvah comes to his hand he should bless with joy — so it appears to me.",
  "3#א": "Koy, etc. — I already wrote above at length on this; and see in Hilchot Orach Chaim — see there.",
  "3#ב": "And if he slaughtered them, etc. Ra'osh wrote: receive blood in a vessel and cover at night; one does not slaughter into a vessel — on this there are many difficulties. Therefore the essence for all difficulties: if it is received for kisuy dam they will consider it certainly chayah and permit its milk; see Peleti. Therefore even if he has prepared earth — nevertheless forbidden on Yom Tov because of permitting its milk.",
  "4#_": "To cover it without blessing — although below regarding kilayim the Mechaber wrote plainly it is a species of behemah and Rama did not correct; Rama was stringent here because he can slaughter a bird — Peri Chadash. And this is insufficient, for then on Yom Tov he would slaughter since you hold it certainly behemah and not cover; better to say Rama relied below on that case which is in the category of safek chayah — and so the matter there.",
  "5#א": "And below it says \"and cover it with earth\" — implies below and above.",
  "5#ב": "Designate with mouth — and mitzvah that he place the earth, as written \"and cover it with earth\"; b'dieved it is not me'akev — like \"the wind covered it.\"",
  "6#_": "He covers with his hand so mitzvot are not treated contemptuously on him as well.",
  "8#_": "And another saw — obligated to cover. Tur gave reason: positive commandment on all Israel; but in Gemara derived from verse \"say to Bnei Yisrael\" — warning on all Israel; see Peleti what he wrote. I also wondered: if one acquired the mitzvah of covering, can he honor another with this mitzvah? From mohal who has a son in Eretz Yisrael to honor another to circumcise — I raised. To instruct another to cover or circumcise as agency is permitted — agent of man is like himself; but by way of honor or as agency forbidden — like Or Zaru'a and Shach.",
  "9#_": "One covering for all; and if he spoke between covering and covering — see above siman 19.",
  "11#א": "Exempt from covering — for it is covered and standing.",
  "11#ב": "Became uncovered again — see Pri Chadash: that he must cover is from safek whether there is rejection regarding mitzvot — for when the wind covered it, it was rejected for him; and from safek we do not bless — Peri Chadash.",
  "11#ג": "If he himself, etc. — if he covered he is not obligated to watch at all whether it becomes uncovered later, for he fulfilled his mitzvah; therefore they cover in streets and places many pass and tread there — and covering is not fulfilled at all.",
  "12#_": "Obligated to cover; and although the first was nullified, nevertheless it returned and revived — no rejection regarding mitzvot; therefore do not bless on covering — this is whether there is rejection regarding mitzvot — safek — Peri Chadash.",
  "14#א": "Exempt from covering — when he cannot drag the blood; but if he can drag behemah blood he drags and covers chayah blood — Rashba.",
  "14#ב": "Or bird, etc. — Bach's view: with bird no need to cover; Taz, Shach, and Pri Chadash challenged him; what Beit Yosef wrote to settle the difficulty is forced; see Peleti where I expanded settling Tur; and there is room for Bach's words; therefore cover without blessing.",
  "14#ג": "Obligated — even though no earth below, since he could have placed earth below — whatever is fit for mixing is not blocked; so Gemara beginning Kisuy HaDam — see there; Atzei Erez wrote it deals when there is earth below — latter authorities challenged against Gemara; see Peleti where I settled his words — there is not so much novelty.",
  "14#ד": "And became neveilah, etc. — Rama wrote this distinction to settle why obligated for chayah and behemah but exempt bird upon bird; Rama's answer is forced; therefore Shach: the case was not one upon the other, only mixed at the side — forced; and what is Maharam's teaching? See Peleti where I wrote proper answer to Maharam. Earth below is nevertheless not me'akev; see Peleti what I expanded on this.",
  "15#_": "Some lifeblood — see Peleti: this law is Rashi's and not found so in other poskim — see there.",
  "16#א": "Even if he has inserted spit — he who showed this ink forbids slaughter except for ill patient's need — Ran.",
  "16#ב": "That if he had — Ra'ah holds inserted spit they did not permit because there is some prohibition; Chachamim did not permit unlike this where there is no prohibition; but according to Ran — for distinction that day is forbidden even in such a case — forbidden; and so Rashba's view.",
  "17#א": "And likewise deaf-mute, etc. — the same applies to adult who does not know shechitah laws at all — Taz.",
  "17#ב": "And exempt from covering — not precisely exempt, but forbidden to cover lest they say shechitah was excellent and eat from it — Shach.",
  "19#_": "Must check — and unlike shechitah where impossible to bless before performing — unlike here where he waits for covering — Shach and Taz.",
  "20#א": "Disqualification due to doubt — here there is no definite neveilah; we do not say animals in presumption of prohibition — most animals even in shechitah are kosher — it is only safek.",
  "20#ב": "Cutting spinal column is general stringency; therefore even bless, for obligated in covering without doubt — Shach.",
  "21#_": "The Sages enacted for him — we did not find in Gemara, only Geonim; therefore many raise objections; nevertheless one who wants to be stringent may; one who wants to be lenient certainly should not protest, for he has Geonim to rely on — perhaps for tikkun olam: they saw breaches eating without covering at all — they enacted this so kisuy mitzvah is remembered; without enactment travelers in western lands deserts would transgress this mitzvah with their hands — therefore for blessing, enactment of Geonim is found — many berachot on Geonic enactments; therefore we do not depart from Rama's words; but all this is western lands and surroundings where one travels long before earth or vessels — no wood with him; in our country where prepared earth is available even if lacking a day or two — do not rely on this and nullify kisuy hadam — clear.",
  "22#_": "And no blood came out — meaning he did not cut veins; if he cut them blood would come out — they lead to blood; and it is taught: obligated to cut veins so blood flows and mitzvah of covering is fulfilled — teaches not required."
});

// --- peleti (5) ---
patchFile('siman_028/peleti/part-001.txt', 'peleti', {
  "3#_": "And one does not slaughter them, etc. The Ra'osh wrote to receive the blood in a vessel and wait until night and then cover it; and Tosafot: one does not receive blood in a vessel — see there. It is difficult for me: we say in Beitzah (daf 8b): when he comes and crushes, a positive commandment comes and pushes aside a negative commandment; and similarly when while covering he crushes — the Gemara challenges: behold Yom Tov is a positive commandment and a negative commandment, etc. How can the positive commandment of covering push aside the positive commandment of Yom Tov? It is possible to fulfill both: receive blood in a vessel and cover at night after Yom Tov passes and fulfill both. And if one may not receive blood at night — that is only a rabbinic decree, and from the Torah it is permitted; how can it push aside a Torah negative commandment? On this the Sages did not uproot Torah law; and study is needed l'chatchila. It must be said with difficulty: certainly the essence of kisuy hadam is to cover immediately when blood leaves the slaughtered animal, and if he delayed he nullified the mitzvah; and the Ra'osh who suggested receiving blood in a vessel and covering at night is at least better than nullifying kisuy hadam entirely; but if he receives in a vessel and covers at night he does not fulfill kisuy hadam properly, therefore it could push aside a negative commandment also to fulfill properly. And similarly we say in Menachot (daf 72): burning fats — its time is all night, nevertheless it overrides Shabbat because a mitzvah at its time is dear; and so here with kisuy hadam — dear is the mitzvah at its time to cover immediately, and it overrides Yom Tov; and study is needed.",
  "8#א": "And another saw it. In the Gemara they derive it from the verse \"say to Bnei Yisrael\" — a warning to all Israel; and Tur wrote a positive commandment incumbent on all Israel like other mitzvot. Taz wondered: we learn from a verse, and it appears one can say: the Torah placed the obligation other than on the slaughterer — meaning the owner of the animal, for the animal is his and likewise the blood; but to slaughter is for his benefit, and to impose obligation on others — who asked this of you that you slaughter and impose covering on us? Therefore Tur wrote this is in the category of other mitzvot; and since the verse teaches this in a particular derivation, all are equal — owner or other.",
  "8#ב": "Another — if the slaughterer acquired the mitzvah of covering, can he honor another with this mitzvah? One should examine: Shach in Choshen Mishpat siman 382 wrote at the end s.k. 3 from Ra'osh that one who is a mohel in Eretz Yisrael may not give his son to another to circumcise and he himself must circumcise; I brought this because I saw people who could circumcise themselves yet honor another to circumcise their son — they nullify the command of Heaven. From this it appears in covering it is plain the slaughterer may not honor another with kisuy hadam. And what is plain to Shach is a doubt to Rama, who wrote in Yoreh De'ah siman 264 in Darkei Moshe in the name of Or Zaru'a: if the father is mohel it is forbidden to appoint another; and Darkei Moshe wrote: study is needed from other mitzvot where one may appoint an agent. We find in Bava Kamma (daf 140): a kohen acquires through service — this is the law of the offering; nevertheless it is explicit one may give another kohen to offer in his place. Terumah is his and incumbent on him to lift — nevertheless we derive agency from terumah \"you\" \"also you\"; and in Yevamot (daf 40) it implies regarding eating menachot: the mitzvah is for the serving kohen to eat, and he may not give to others not of his father's house. Therefore it appears an agent of a man is like himself and the sender receives reward as if he did it; regarding sin, the sender to commit sin — were it not for the reasoning \"words of the master and words of the disciple — whose words are heard?\" the sender would be liable as if he did it; so in a good measure regarding mitzvah he receives reward. Why hesitate to appoint an agent since his reward is not diminished? This applies when he appoints him as agent saying \"do this as my agent\" — plainly an agent of man is like himself; but if he honors him by way of honor in this mitzvah he does not receive reward, for the mitzvah was in his hand and he gave it to another gratuitously — agency does not apply; therefore regarding eating we do not say regarding sin \"an agent of man is like himself,\" as explained there in the Gemara — a fortiori regarding mitzvah; and this is correct for halakhah: distinguish between way of honor and making him an agent.",
  "12#_": "Blood that fell — see Kereti; and study is needed for the first view below siman 334 s.k. 3 according to Shach's correct gloss that we do not say at all that even if it increased to less than sixty parts it returns and revives; and in this we do not say rejection regarding mitzvot — all the more we do not say regarding prohibitions; if so, what is said here?",
  "14#_": "Or bird — and Bach wrote bird upon behemah is exempt; and latter authorities all challenged him; the essence is from Tur who wrote in Ba'al HaItur: one who slaughtered bird or chayah and slaughtered behemah upon it — exempt from covering behemah; and afterward chayah — obligated to cover upon it. Beit Yosef wondered: behold the baraita is arranged at the beginning of chapter Kisuy HaDam: slaughtered chayah and afterward behemah — exempt; slaughtered behemah and afterward chayah — obligated. Therefore Bach explained Ba'al HaItur began with two — bird or chayah and afterward behemah — exempt; and in the obligation — behemah and afterward chayah obligated, and did not mention bird — implying with bird too exempt, because bird blood is minimal. This reason is not straight at all in the eyes of latter authorities, as Taz expanded. It appears to me Beit Yosef brought in Hagahot Maimoniyot: if he slaughtered a kosher hen and again slaughtered and it became neveilah — obligated to cover; and Beit Yosef wondered: behold it is chayah blood below and behemah blood above. These words are in the gloss to distinguish known cases to settle Beit Yosef's difficulty. Shach in Nekudot HaKesef wanted to say there it deals when he did not slaughter upon it, only mixed at the side — forced; also for Beit Yosef and Rama this was not hidden, only difficult — what does Maharam teach us? Plain: blood mixed with blood — obligated to cover. Therefore it appears Maharam's difficulty: why when slaughtering behemah above does he not cover for chayah blood below? If behemah blood interposes between chayah blood and earth — what of it? We rule in chapter Lulav HaGazul: min b'mino does not interpose; or chayah blood and behemah blood — although for mixtures essentially they are both blood, here for interposition in the mitzvah it must be min b'mino — both in the category of kisuy hadam; but if one is not in kisuy hadam, for interposition in the mitzvah it is not called his species — there is no species requiring covering, so how does it not interpose and it is not his species? Or who says he does not cover only because of interruption or interposition — only if they see him cover behemah blood as proper covering and bless, they will not distinguish chayah blood below, only think it is chayah and permit its milk. From these two reasons one must require covering in Maharam's case: if below is bird blood requiring covering and above bird blood not requiring covering — min b'mino, for his species requires covering, only due to neveilah he is exempt from min b'mino and does not interpose, and permitting its milk does not apply. Maharam's words are clear. Returning to Ba'al HaItur: in the Gemara at the beginning of Kisuy HaDam it mentioned earth below is me'akev, earth above — from the baraita slaughtered behemah and afterward chayah he covers, yet there is no earth below; and it answers: whatever is fit for mixing is not me'akev. One can understand: perhaps the baraita deals when there was earth below; if the baraita's language is slaughtered behemah and afterward chayah and it does not teach he placed earth on behemah blood — it implies earth does not interpose between behemah and chayah, unlike the reverse slaughtered chayah and afterward behemah where certainly no earth interposes, for it was already covered — only perhaps before slaughtering behemah he placed earth below and slaughtered behemah and afterward chayah, or the reverse. But what of behemah blood below near that earth interposing between chayah blood and earth? Only if we say all is min b'mino — what difference behemah or chayah, min b'mino does not interpose; and what interposes above in behemah blood is due to permitting its milk as above. But if min b'mino interposes, why need earth below? Behemah interposes; it must be there was no earth below, and the Gemara is precise that no earth below is not me'akev. Tosafot in Sukkah chapter Lulav HaGazul wrote: this \"if min b'mino interposes\" is uncertain — it should have been asked in chapter Behemah HaMekasheh — see there; rather Rava resolves for himself min b'mino does not interpose; and so the Gemara challenges well from chayah blood above that earth below is not needed, and why care if behemah blood interposes — and if it were min b'mino, resolve the question that min b'mino does not interpose — and so is the sugya throughout the Talmud; and the Gemara rejected \"whatever is fit for mixing,\" etc. But since we rule like Rava that min b'mino does not interpose, the challenge and \"let us drag it\" are settled: what does dragging accomplish for earth below — behold there is earth below as written; and study is needed. With this, Ba'al HaItur's words that it deals when there is earth below are true; and what they challenged from the Gemara is no challenge, for the Gemara was unresolved and we say according to the conclusion. Behemah blood and chayah blood are one species; but behemah blood and bird blood are not one species — the nature of this is not like that in every matter of quantity and quality; if so, Ba'al HaItur deals when there is earth below according to the conclusion, therefore slaughtered behemah and afterward chayah he covers and need not drag, for there is earth below and no interposition; but bird above — what does covering help? There is no earth below; and if anyway there is interposition of behemah and chayah and bird — it is species where there is no mino, and it interposes; in any case dragging is needed to cover with earth; and Bach's words are correct — all on one reasoning; and study is needed."
});

// --- pitchei-teshuva (14) ---
patchFile('siman_028/pitchei-teshuva/part-001.txt', 'pitchei-teshuva', {
  "1#_": "<b>Shehecheyanu.</b> See Magen Avraham siman 22 s.k. 1.",
  "2#_": "<b>To slaughter a bird as well.</b> See responsum Zichron Yitzchak siman 110: Rama was precise in his wording — wrote to slaughter bird and did not write chayah or bird — because essence of kisuy mitzvah is to cover immediately when blood leaves the slaughtered — see there.",
  "3#_": "<b>Exempt from covering.</b> See Magen Avraham siman 485 s.k. 6.",
  "4#_": "<b>Obligated to cover.</b> Pri Chadash wrote; and so agreed Pri To'ar: cover without blessing because \"no rejection regarding mitzvot\" is an unresolved question not clarified; see Magen Avraham siman 485 s.k. 6 — his view appears he covers with blessing here; see Sefer Be'er Yaakov what he wrote and raised like Pri Chadash; however he wrote: proper to slaughter another bird first and bless on covering, then cover this one that became uncovered; but if he has no other bird — certainly cover without blessing — see there.",
  "5#_": "<b>Obligated to cover.</b> Avnei Nezer; and see in Sefer Tefillah Lemoshe: if chayah and bird blood mixed in another chayah and bird blood already covered and became uncovered — exempt to cover it as in seif 11; or already covered part of its blood — need not cover more as in Shach; possibly in such a case even without appearance of blood obligated in covering since all blood is species requiring covering, only exempted in part; and in such mixture possibly for all blood in blood is not nullified — study needed for law — see there.",
  "6#_": "<b>Need not cover all the blood.</b> [See responsum Mishkenot Yaakov siman 13 who brought proof for Razah brought in Beit Yosef that one must cover all of it. And on what Shulchan Aruch wrote here \"and he drags it,\" etc. — he brought proof for R' Meir ben Natan brought in Beit Yosef that dragging is not required — see there.]",
  "7#_": "<b>If he had.</b> See Sefer Tiferet Lemoshe: there is no halakhah like \"there is one who says\" — see there.",
  "8#_": "<b>And exempt from covering.</b> Shach wrote: in Talmud it implies he may not cover, etc.; see responsum Or Zaru'a, Panim Me'irot, part 1, siman 15, who rejected his words: in Talmud it does not imply so at all; he raised there is no prohibition to cover — see there.",
  "9#_": "<b>How should he act, etc.</b> [It appears this is specifically if he needs all the blood; but if not, he can cover part and use the rest for his need from the remaining blood, as above Shach; and see Taz below siman 117 s.k. 4.]",
  "10#_": "<b>Kill by stabbing or uproot.</b> [See responsum Noda Biyhudah, second series, part 4, siman 10: asked regarding a man whom God enriched with broad inheritance, forests and fields with chayot — whether permitted to go himself to hunt with burning reed, or forbidden because of tza'ar ba'alei chayim or bal tashchit; answered: by law no prohibition, for all that man needs — no tza'ar ba'alei chayim; tza'ar ba'alei chayim applies only to its pain and leaving alive, not to killing; and no bal tashchit, for he benefits from hide and does not destroy path; further, essence of bal tashchit prohibition is not destroying what man can benefit from; but thing with no loss to anyone — no bal tashchit; these chayot while alive have no benefit, only in death in hides and flesh — certainly no bal tashchit; nevertheless unseemly trait — cruelty; not his craft; also prohibition putting himself in danger; also causes mention of sins; one whose livelihood is such hunting — no choice; but one whose main intent is not killing — forbidden to do so — see there; and see responsum Shemesh Tzedakah, part 4, siman 18 and 57 on the above matter.]",
  "11#_": "<b>He checks the lung.</b> See responsum Tzemach Tzedek siman 115: regarding checking gizzards in force-fed geese — enactment to check — may cover beforehand; and not compared to lung — see there; and Pri Megadim brought it. It appears the same regarding goose intestines where bubbles are common — need checking as below siman 46 — cover beforehand too; and so wrote in responsum Har HaCarmel, Yoreh De'ah part, siman 8, middle of answer — see there.",
  "12#_": "<b>Similar to this.</b> Avnei Nezer; see responsum Or Zaru'a, Panim Me'irot, part 1, siman 15, middle of answer — settles Bach's view and raised for law his words that safek in shechitah with defective knife — need not cover — see there.",
  "13#_": "<b>They are stringent.</b> See responsum Nishmat Shaul, part 2, siman 47 and 57: likewise any shehiyah — cover with blessing — see there; see responsum Beit Yitzchak siman 86.",
  "14#_": "<b>The Sages enacted for him.</b> See Tiferet Lemoshe who wrote: study needed whether permitted to do so when slaughtering for ill on Shabbat — against \"there is one who says\" in seif 16; and according to what is written there we do not rule like \"there is one who says\" — if so, absorbing blood in garment is also forbidden because of exertion — see there."
});

// --- rabbi-akiva-eiger-yd (6) ---
patchFile('siman_028/rabbi-akiva-eiger-yd/part-001.txt', 'rabbi-akiva-eiger-yd', {
  "1#_": "(Siman 28, Shach s.k. 10) <b>And I will receive blood in a vessel.</b> It is hard for me: in such a case forbidden because of nullification of a vessel from its place — see Shulchan Aruch Orach Chaim (siman 265); and perhaps one can say: he comes to teach even if he has a vessel attached to the ground — in such a case it would be fit to slaughter over this vessel, for it is not called nullification of vessel from its place, since anyway the vessel is attached and cannot be moved on Shabbat; see Minchat Ani (siman 336 s.k. 4) — proven he holds even pouring into attached vessel is nullification of vessel from its place — study needed. And perhaps one can say: because of mitzvah of covering it is permitted to nullify vessel from its place — see Rashi Shabbat (daf 155b) and Magen Avraham (siman 263); and still study needed: perhaps here it is worse, for at the time he transgresses nullification of vessel he has not yet fulfilled kisuy, and also safek obligation of covering; in my humble opinion: there when blood is covered there is no obligation to cover; and if it became uncovered again he must cover; if so, here too one can say: if he did not place earth below he is not obligated to cover; nevertheless if it became uncovered again he must cover; if so, \"and he places\" specifically — mitzvah of covering is specifically with placing; here too when he found loose earth and slaughtered upon it he did not fulfill kisuy; if uncovered, since blood is exposed, obligation to cover; and when he must drag blood and place earth below as proper covering — in the simple case: difference when slaughtering on loose earth whether must drag and place loose earth; whenever blood is exposed and obligated to cover — obligated in placing earth below; and exactly like \"there was no earth below\" must drag as in seif 7; likewise according to one view: when loose earth is by itself below, it is as if no earth at all below.",
  "3#_": "(Seif 7) <b>He must drag the blood.</b> This is Rashba's words who learned from blood on the knife explained in sugya he drags it; and that of seif 14 slaughtered behemah and afterward chayah — obligated to cover — explained sugya covers only above and need not drag — this is truly Tosafot's difficulty, left in difficulty; see Shach s.k. 20. In my humble opinion one can say: in truth the law is equal — meaning Ra'ah's view: plain to Talmud that blood on knife requires dragging, because there is no concept of covering on the knife; one cannot say covering without loose earth suffices because fit for mixing — therefore when slaughtered behemah and afterward chayah no need to drag, only they challenge on kodshim to exempt entirely since no earth below and not fit for mixing — on this they challenge: nevertheless drag like blood on knife — no covering on knife, drag and cover. According to Rashba one can say covering on knife also applies, only Talmud's precision from \"obligated to cover\" and does not teach \"he covers it with earth\" — at first glance difficult: this precision can be inferred also from baraita body behemah and afterward chayah that teaches \"obligated to cover\"; and it appears the precision is only because it does not teach \"he covers it with earth\" — implying dragging because of earth below; but from baraita slaughtered behemah one can say he relies on why it teaches chayah and therefore behemah exempt from covering and need not drag; if so, proven in behemah and afterward chayah he is obligated without dragging; and if chayah and afterward behemah — reason like \"the wind covered it.\" One can say in truth where no earth there is no covering; and from exempt it follows they do not require dragging in covering at all; therefore he inferred only from blood on knife where one might think he relies on dragging — should have taught plainly \"he covers it with earth\"; therefore one can say our version is so: initially they challenge: though impossible below, etc. — was it not taught slaughtered behemah? meaning: if obligated to cover, it is dragging; likewise to drag; and even if you say he covers without dragging — likewise do above; and on this they answer it does not deal with dragging; there it suffices with covering above — whatever is fit for mixing; but for kodshim where R' Eliezer: for mixing entirely exempt — on this they challenge from blood on knife — dragging; likewise to drag. In truth since compelled from blood on knife he drags it — likewise slaughtered behemah and afterward chayah he drags it; and that \"and afterward behemah\" exempt — whatever is covered even in something that is not earth is exempt from covering, for nevertheless it is covered. \"The wind covered it\" — even in something that is not earth; and examine well.",
  "4#_": "(Seif 9) One covering for all. Explained in sugya Rabbanan hold: bird does not need to teach that covering is required for chayah separately and bird separately — only if it comes to divide; and R' Yossi holds division is from its blood; therefore if it comes, he covers each separately; see Tosafot there explanation of their words: even R' Yossi is uncertain whether concerned for father's seed; and according to the side that we are concerned — proven he holds like Rabbi Yonatan: no need to divide, as explained beginning Orach Chaim — behold one depends on the other; nevertheless Talmud seeks to answer the other side that we are not concerned for father's seed — like Rabbi Yoshiah; therefore answers: from its blood; and although still somewhat difficult: one could say R' Yossi's view that he covers chayah separately and bird separately is from safek, since uncertain whether concerned for father's seed — uncertain whether like Rabbi Yoshiah or R' Yossi; therefore here too stringent: perhaps like Rabbi Yonatan and no need to divide bird — must say R' Yossi holds that by law certainly must cover each separately; nevertheless difficult for law: after we rule safek whether concerned for father's seed — we are uncertain in law whether like Rabbi Yoshiah or R' Yossi; rule here too stringently: must cover each separately. Afterward I found in Az Nidberu he stood on this in responsum of Maharam of Lublin and forced it. And why is it hard for me below (siman 259 seif 17) in Hagahah: one who made his son swear not to borrow without Reuven and Shimon's permission, and one died — can borrow with the other's permission; source from Rashba; and for law we are uncertain whether halakhah like Rabbi Yonatan or Rabbi Yoshiah from safek whether concerned for father's seed — behold one depends on the other; and study is needed.",
  "5#_": "(Seif 11) <b>And if it became uncovered again — obligated to cover</b> — without blessing. And for koy in such a case one can say no need to cover — double safek: perhaps behemah; and perhaps rejection regarding mitzvot. And one can argue: the two safekot did not arise together — immediately when he slaughtered he became obligated in covering from safek; afterward when wind covered, second safek arose whether rejection regarding mitzvot; and study is needed.",
  "6#_": "(Shach s.k. 16) <b>For there is no rejection regarding mitzvot.</b> This too is only safek that perhaps there is no rejection regarding mitzvot — cover without blessing.",
  "7#_": "(Seif 20) <b>And if safek treifah found — cover without blessing.</b> See Torat HaDeshen who expanded: we are not concerned lest they see him covering and eat the flesh and say he covers from safek. He wrote: also not proof from covering koy — there different, for signs of chayah in horns and hooves are also needed. Nevertheless since we do not find this concern except regarding deaf-mute, imbecile, minor — there most actions defective — we do not infer other safekot from them — end. And I wonder why he wrote this as decisive without proof — for it is compelled from Tosafot's difficulty there s.v. sippa: how from their blood or bird from safek forbidden to act for covering — positive and negative commandment — they needed their answer that sugya holds in safek certainly obligate covering and we are not concerned they will say excellent shechitah; if so, also for bird permit — see there. Proven explicitly: in safek obligate covering. And more: conclusion Rabbanan fed up with the matter disagree — behold Chachamim obligate in shechitah of deaf-mute, imbecile, minor in covering; although their shechitah forbidden from safek — nevertheless obligate covering and no concern they will say excellent shechitah; and R' Meir who exempts also permits for bird; therefore he holds most actions defective; why exempt from covering. But for this matter of safek obligating covering we find no one disagrees with Rabbanan — clear proof without answer. And I saw Pri Megadim explained Bach's intent: even in safek without strong presumption of prohibition — exempt from covering by law, since forbidden from safek not in \"that may be eaten.\" This too is astonishing: Chachamim obligate deaf-mute, imbecile, minor in covering, as above; and presumably those Chachamim of R' Meir are mishnah Chachamim earlier: slaughtered and treifah found — exempt from covering — from verse \"that may be eaten\" as there in sugya. And more: even if we force those Chachamim are not these Chachamim and hold treifah must cover; therefore safek in shechitah must cover from safek — nevertheless the question itself: why do Rabbanan disagree on the first part from difficulty of questioner on bird from covering? Perhaps truly those Rabbanim are they who expound \"that may be eaten\" — therefore exempt in safek since not permitted to eat; if so, every safek must cover from safek lest not treifah and in \"that may be eaten\" — clear. <b>Further</b> Pri Megadim wrote there: even rabbinic treifot exempt from covering — nevertheless not in \"that may be eaten.\" Hidden from sugya Chullin (daf 27b): they challenge Necher and Ma'aker, etc. — nechirah is its shechitah; nevertheless rabbinically forbidden in nechirah. <b>However</b> this can be rejected: they challenge well: this mishnah of Necher is the end of mishnah \"slaughtered and treifah found\" — first teaches they disagree on treifah, then teaches Necher and Ma'aker — all exempt; therefore challenge well: one who obligates on treifah who does not expound \"that may be eaten\" — only nechirah is not shechitah at all; if no shechitah for Torah matter, say nechirah is its shechitah — only forbidden rabbinically — only like treifah must cover. Similarly they challenge further: teach \"slaughtered and needs blood — how act? necher or ma'aker\" — also on this path: since requires specifically necher and not suffice to make treifah — therefore holds treifah must cover; therefore say nechirah is its shechitah. However, proven from sugya Chullin (daf 86a): not only \"go out and trample\" which is shechitah of R' Eliezer, etc., but even \"go out and necher,\" etc. — \"as I commanded you\" — these have no shechitah from Torah — would have been obligated in covering although treifah exempt; reason of R' Meir: verse \"that may be eaten\" — as said there explicitly. Proven: rabbinic prohibition does not remove mitzvah of covering."
});

// --- nekudot-hakesef (3) ---
patchFile('siman_028/nekudot-hakesef/part-001.txt', 'nekudot-hakesef', {
  "1#_": "(Siman 28, Taz s.k. 12) He wants to reconcile the words of Hagahot Maimoniyot in the name of Maharam — and it is forced; the matter is clear as I wrote in my Mareh Makom: Hagahot Maimoniyot deals when they were mixed together, for there they wrote thus on what Rambam wrote there: if blood was mixed in wine or in blood of behemah we view them as if they were water — if it is possible that the appearance of blood would be seen, he must cover it in this measure as if it were water — and Hagahot Maimoniyot wrote on this: obligated to cover, as the plain mishnah; and so my teacher ruled on one who slaughtered a kosher hen and again slaughtered another and it became neveilah — he must cover — end of his words; behold as I explained.",
  "2#_": "(s.k. 15) And it is astonishing, etc. It is not difficult at all; you overlooked the words of Maharshal, chapter Kisuy HaDam, who ruled in truth in a matter where a defect arose — that one blesses before shechitah — and this is like Rashi's view (and it also appears you overlooked Rashi's words too): since when he removes it from neveilah status he can bless; and he brought Maharshal there; and Beit Chadash at the end of siman 19. However in Siftei Kohen siman 19 s.k. 2 I wrote that from Yerushalmi it appears like Or Zaru'a — see there.",
  "3#_": "(s.k. 17) He challenged Rama. And his words are not compelled; also what he challenged Beit Chadash is not difficult at all, for in truth he covers afterward with earth — only the blessing was not enacted l'chatchila on earth; and from Levush there is no proof that Darkei Moshe did not see it; he also did not see Ramban's words that I brought in Shach s.k. 29; and we must reconcile the words of the Geonim, for all their words are words of tradition."
});

// --- kaf-hachayim (24) ---
patchFile('siman_028/kaf-hachayim/part-001.txt', 'kaf-hachayim', {
  "1#_": "<b>A) [Seif 1] One who slaughters chayah or bird must cover its blood.</b> The reason is written in Midrash Rabbah, parashat Bereishit: because they buried Abel and the Holy One blessed be He gave them reward — two blessings they bless on them: one for shechitah and one for covering blood — see there; meaning: as they buried him and covered his blood, so their reward that their blood requires covering — measure for measure.",
  "2#_": "<b>B) There. Must cover its blood.</b> He should hasten to cover immediately, for we hold a mitzvah at its time is dear; however if he did not cover immediately and covered afterward — he fulfilled the positive commandment as required, only he did not treat the mitzvah at its time dearly. And if he did not cover immediately and covered after a short time — still called mitzvah at its time, only not among those who hasten mitzvot. Machazik Berachah, Orach Chaim part 1, Zivchei Tzedek part 1.",
  "3#_": "<b>C) There. Must cover its blood.</b> Also with warm ashes permitted to cover — Taz Orach Chaim siman 498 s.k. 15. And Da'at Kedoshim at end of this siman wrote: do not cook blood or salt before covering; therefore proper the ashes not be yad soledes bo. And Gidulei HaKodesh wrote there part 6: on this some Torah students wondered — opposite Taz above; and wrote to settle: specifically lower earth one does not cover with warm ashes, for necessarily he waits a bit before covering above and at time of upper covering blood already cooked by lower ashes; but upper earth permitted with warm ashes — see there; and Beit Din Mani in Likutei Halachot part 157. Zivchei Tzedek part 2 wrote there Zivchei Tzedek: therefore warn slaughterers not to absorb shechitah blood in kiln that has fire and ashes that are yad soledes bo.",
  "4#_": "<b>D) If</b> after he slaughtered he consecrated the blood — he must cover because mitzvah of covering preceded consecration — so we learned in Tosefta. The same if he consecrated the chayah or bird after slaughter — Rambam chapter 14 of Hilchot Shechitah law 3; Minhag in Hagahot Tashbetz part 5; Zivchei Tzedek part 3.",
  "5#_": "<b>E) There. Whether on his side now, etc.</b> For Sages taught: \"that hunts\" — I have only one who hunts; hunted ones standing by themselves — from where geese and chickens? Teach \"hunting\" in any case. If so, why \"that hunts\"? Torah teaches proper conduct: a person should not eat meat except with this preparation — Chullin 83a. Rashi: except with this preparation — as if hunting not prepared for him, meaning do not eat meat frequently lest he become poor — end; and Beit Yosef brought it; Taz s.k. 1.",
  "6#_": "<b>F) There in Hagahah. But shechitah is kosher, etc.</b> Even for himself; and so Darkei Moshe; and so Beit Yosef and Rashal, chapter Kisuy HaDam siman 1, and other latter authorities — not like Bach who forbids for himself — Shach s.k. 3; Pri Chadash part 3; Likutei Halachot part 2; Kereti part 1; Shem Chadash part 2; Zivchei Tzedek part 4.",
  "7#_": "<b>G) However</b> where people are lax in mitzvah of covering — not covering properly, or not blessing on covering or shechitah — penalize and obligate lashes; also forbid shechitah to transgressor because of erecting a fence — Shach there; Likutei Halachot there; Shem Chadash there; Shomer Emunim part 3; Zivchei Tzedek part 4; Zivchei Tzedek part 5; and so above siman 19 part 1.",
  "8#_": "<b>H) And even</b> only that slaughterer lax in this mitzvah — penalize and lashes and forbid meat to transgressor because of erecting a fence — Shem Chadash there; Shomer Emunim there; Zivchei Tzedek part 6.",
  "9#_": "<b>I) [Seif 2] Must bless before covering, etc.</b> As Pesachim 7b: all mitzvot bless before performing. If he did not bless before covering — he does not bless after covering — Shem Chadash and Turei Zahav part 3, unlike Pri Chadash. And Mishnah Berurah agreed part 3 because of safek berachot. Zivchei Rambam in Tamidim part 7; Mani part 2; Zivchei Tzedek part 7; and from those poskim it appears even within kedei dibbur one does not bless after covering; although Kometz part 2 holds one may bless within kedei dibbur of covering; and Mani's view leans in Likutei Halachot part 7; nevertheless we hold safek berachot lehakel even against Maran and even against majority, as Orach Chaim siman 18 part 7 — see there; rather bless in heart or without God's name and kingdom. See above siman 19 part 6.",
  "10#_": "<b>J) There. On covering blood with earth.</b> Although we do not find anywhere mentioning the detail in the blessing except generally — it would suffice \"on covering blood\" alone; nevertheless here different, performing two mitzvot — below and above — learned from \"with earth\"; must say \"with earth\" for two mitzvot — Taz s.k. 3. But Rambam and other great ones brought formula \"on covering blood\"; and Rashbatz in Yavin Shemuah. And Kitzur Halachot wrote law is as Chayei Adam: custom when standing to say \"on covering blood\" and no more. But Shach s.k. 29 wrote their custom to say \"on covering blood with earth\"; in his long book brought so from Rokeach, Geonim, Tashbetz, Maharshal — see there; and custom of land of Tzvi and Egypt like Maran and his colleagues to say \"on covering blood with earth.\" Neharah Neharah and Pestia. Machazik Berachah part 2; however what he wrote \"and so custom,\" etc., to say on kisuy hadas with earth — meaning also say word \"with earth\"; but regarding word \"blood\" with hei — on the contrary Shulchan Aruch's formula without hei — this is per another version written in part 6 afterward.",
  "11#_": "<b>K) There. On covering blood with earth.</b> And so formula in Tur and shechitot of Mahariu, end siman 8; Levush; Yeshuot Yaakov, chapter Kisuy HaDam siman 12; Shem Chadash part 3; Chayei Adam, general 8 part 4; Kometz part 2; Ahel Yitzchak siman 24 part 11; Mani part 2; however in Tosefta Berachot chapter 6 part 16 formula \"on covering the blood\" with hei; and so Rambam chapter 14 Hilchot Shechitah law 1; Lev Avraham siman 108; Rokeach siman 380; Minhag in Hagahot Tashbetz part 8; Ben Ish Chai, parashat Vayelech part 3; Neharah Neharah and Pestia.",
  "12#_": "<b>L) And if</b> he said only \"on covering blood\" and did not say \"with earth\" — he fulfilled. Chayei Adam there; and simple, since several Geonim hold even l'chatchila one says only \"on covering blood\" without word earth, as above part 10; if so, even where practiced to say \"on covering blood with earth,\" if he did not say \"with earth\" — plainly he fulfilled.",
  "13#_": "<b>M) And before</b> blessing say for sake of unification, etc.: \"Behold I come to fulfill positive commandment of covering blood, as it is said 'and pour out its blood and cover it with earth,' to repair the root of this mitzvah and all 613 mitzvot included in it in the supernal place. And may it be pleasant,\" etc.",
  "14#_": "<b>N) With earth</b> — beit with segol, not shva. Mishnah Berurah part 3; Mani part 2; Zivchei Tzedek part 9.",
  "15#_": "<b>O) There in Hagahah. One who slaughtered first time blesses shehecheyanu on covering.</b> However Pri Chadash part 5 wrote: for law, since Tosafot and Rashba agree not to bless and their words appear primary; and safek berachot lehakel — so we rule, unlike Hagahah — see there. And Likutei Halachot part 2; and responsum Ba'ei Chayei, part 4, siman 22: world does not practice to bless, for not a mitzvah with joy — unlike the Rav from Shulchan Aruch — see there. Turei Zahav siman 4 part 7; also Rikanti wrote on Rama's words: not practiced and not mentioned in Talmud — Zivchei Tzedek part 7; and Shomer Emunim part 5: certainly do not enter safek berachah; and Kometz part 3: to exit dispute, take other vessel or new fruit and bless on it and intend also for covering; if not — do not bless — safek berachot lehakel; and Mani part 2; and Zivchei Tzedek part 11: custom in Baghdad not to bless shehecheyanu on covering. However where practiced to bless — do not neglect them, for where there is custom we do not say safek berachot lehakel, as Orach Chaim siman 7 part 2 — see there.",
  "16#_": "<b>P) [Seif 3] Koy which is safek chayah and kilayim from behemah and chayah must cover its blood, etc.</b> It implies both ram on she-gazelle and gazelle on she-goat — both must cover and do not bless; and so Bach; and so Derishah part 1: even ram on she-gazelle whose mother is chayah must cover and not bless; and so Rav Mateh Asher siman 18: even ram on she-gazelle whose mother chayah — also do not cover on Yom Tov and do not bless — unlike Rashal, Taz, and Shach; rather like Bach, Derishah, and colleagues — see there; and so Sefer Beit Meir; Zivchei Tzedek part 12.",
  "17#_": "<b>Good) There. And does not bless.</b> Lest it be behemah and blessing in vain, and transgress \"do not take,\" etc. — Levush.",
  "18#_": "<b>Live) There. And one does not slaughter them on Yom Tov.</b> Since must cover and on Yom Tov may not cover — do not slaughter l'chatchila — Shach s.k. 8; Pri Chadash part 7; Likutei Halachot part 6; Zivchei Tzedek part 10.",
  "19#_": "<b>T) There. If he slaughtered them he does not cover its blood.</b> Even if prepared earth — lest observer say certainly chayah, for otherwise they would not trouble to cover on Yom Tov and come to permit its milk — Shulchan Aruch Orach Chaim siman 498 seif 18; and see Hagahah there: if slaughtered in middle of courtyard, permitted to cover if prepared earth — see there; and in our words for its sake.",
  "20#_": "<b>K) There. And at night if recognizable he may cover.</b> And they cannot receive blood in vessel to cover at night, for one does not slaughter into vessels — Tur; reason as above siman 11 seif 3 lest they say receiving blood to throw to idolatry — see there. Bach wrote: nowadays b'dieved if slaughtered on Yom Tov can receive in vessel even l'chatchila; nevertheless better place earth and pebbles in vessel before receiving — see there; Beit Din Shach s.k. 10. Derishah wrote: perhaps here too concern before observer he took earth to cover koy blood by sage's command and they will permit its milk; and so Darchei Shalom; Minhag in Hagahot Tashbetz part 14; Likutei Halachot part 3; and Shem Chadash agreed part 4; Turei Zahav in Orach Chaim siman 498 s.k. 34; Minhag Tziyon, general 23 in Asheret part 10; Zivchei Rambam siman 19 in additions part 4.",
  "21#_": "<b>KA) Koy</b> lacking a limb — permitted to slaughter on Yom Tov and receive blood in vessel and cover at night, since we do not offer lacking limb to idolatry — She'erit Shmuel end part 3; Zivchei Tzedek part 15. However according to reason we wrote above part 18 — appears even in such case not l'chatchila.",
  "22#_": "<b>KB) [Seif 4] Buffalo — they practice not to cover its blood.</b> It is re'em mentioned in the verse — Beit Yosef; Levush; Zivchei Tzedek part 14; it is the species called in Arabic jamus; larger than ox and similar — so Ra'avad on Amos siman 5 verse 22; and Yeshayah siman 1 verse 11; and Ralbag Melachim 1 siman 1 verse 10: re'em is a species of fat large cattle — end; and in root shoresh mara: species of large cattle; and Rambam chapter 1 Hilchot Ma'achalot Assurot law 8: such as wild ox and re'em which are ox species — end; Beit Din Zivchei Tzedek part 16; see below siman 80 seif 3 and siman 297 seif 7.",
  "23#_": "<b>KG) There in Hagahah. And some are uncertain in buffalo, etc.</b> They say it is koy — Darkei Moshe part 1 in shechitot of Mahariu; Beur HaGra part 7; therefore do not slaughter on Yom Tov like koy.",
  "24#_": "<b>KD) There in Hagahah. Therefore good to cover without blessing.</b> And mitzvah to heed Geonim to cover as proper covering, only not bless from safek lest this not be the buffalo of Geonim's words — Pri To'ar part 6; Zivchei Tzedek part 15."
});

// --- yad-avraham (2) ---
patchFile('siman_028/yad-avraham/part-001.txt', 'yad-avraham', {
  "1#_": "(Siman 28, seif 8) The one who slaughtered covers. See Kerem Shlomo who wrote: by way of agency and Torah law of agency — not by way of honor — the slaughterer and father may instruct another to cover or to circumcise; not as Shach wrote in Choshen Mishpat siman 382 that one who is a mohel in Eretz Yisrael may not give his son to another to circumcise. And in Siftei Kohen he wrote that Shach also concedes regarding agency it is fine. And so in Shabbat (daf 133): they challenge \"if there is another, let another act,\" etc. — see there, it implies even if he can circumcise himself it is possible through another when there is another; and so in Turei Zahav; and I expanded in Magen Avraham; and in Binat Adam he wrote similarly; and Shach — because the verse revealed \"and cover it\" and likewise \"and Avraham circumcised\" implies himself, and as said in Sotah (daf 27), Menachot (daf 93), and he is like Rabbi Yoshiah in Bava Metzia (daf 95); and the sugya in Shabbat (daf 133) that this is only a branch of the mitzvah that the father circumcise himself, and a branch of a negative commandment. And in such a case he wrote in Siftei Kohen siman 195 that because the mitzvah is more incumbent on him there is no mitzvah from the preferred way that overrides Shabbat. And study is needed: in Menachot (daf 64) we find a mitzvah that overrides Shabbat regarding a korban.",
  "2#_": "(Seif 11) The wind covered it, etc., and it became uncovered — obligated to cover. See Turei Zahav: is it specifically with things one does not cover, or even if he covered with things one covers? And it appears proven from Tosafot at the beginning of chapter 25 (daf 87b), s.v. tzarich: even if he covered with things one covers — because the mitzvah is that he place the earth above."
});

